'Units_Guide_Base' => 'বেস ইউনিট: "বেস ইউনিট" ঘরটি ফাঁকা রাখুন। স্টক সবসময় এই ইউনিটেই গণনা করা হয়, যেমন পিস।',
'Units_Guide_Sub' => 'সাব-ইউনিট: একটি "বেস ইউনিট" বেছে নিন, তারপর "অপারেটর" ও "অপারেশন ভ্যালু" দিয়ে সেটিকে ওই বেস ইউনিটে রূপান্তর করুন।',
'Units_Guide_Example_Multiply' => 'উদাহরণ: একটি বক্স, যার বেস ইউনিট পিস, অপারেটর * এবং ভ্যালু 12। 1 বক্স বিক্রি করলে স্টক থেকে 12 পিস কমে।',
'Units_Guide_Example_Divide' => 'উদাহরণ: একটি গ্রাম, যার বেস ইউনিট কিলোগ্রাম, অপারেটর / এবং ভ্যালু 1000। 500 গ্রাম বিক্রি করলে স্টক থেকে 0.5 কিলোগ্রাম কমে।',
'Units_Guide_Note' => 'শুধু বেস ইউনিটগুলোকেই "বেস ইউনিট" হিসেবে বেছে নেওয়া যায়, এবং কোনো ইউনিটের সাব-ইউনিট থাকা অবস্থায় সেটি মুছে ফেলা যায় না।',

'Amount_Paid' => 'পরিশোধিত পরিমাণ',
'Payment_Amounts_Help' => 'পরিশোধিত পরিমাণ বকেয়া নিষ্পত্তি করে এবং বাকি কমায়। প্রাপ্ত পরিমাণ হলো হাতে নেওয়া নগদ: এটি শুধু ফেরত দেওয়ার ভাংতি হিসাব করতে ব্যবহৃত হয় এবং বাকি পরিবর্তন করে না।',

'Show_Tax_Desc' => 'চেকআউটে পুরো বিক্রয়ের ওপর প্রযোজ্য কর, যা মোট অংশে আলাদা "অর্ডার ট্যাক্স" লাইন হিসেবে ছাপা হয়।',
'Show_Items_Tax_Desc' => 'প্রতিটি পণ্যের নিজস্ব করের যোগফল, যা "মোট আইটেম ট্যাক্স" লাইন হিসেবে ছাপা হয়। চালু থাকলে সাবটোটাল এই কর ছাড়াই দেখানো হয়।',
'Show_Discount_Desc' => 'পুরো বিক্রয়ের ওপর দেওয়া ছাড় (পয়েন্ট ছাড়সহ), যা মোট অংশে আলাদা লাইন হিসেবে ছাপা হয়।',
'Show_Product_Discount_Desc' => 'প্রতিটি পণ্যের নিজস্ব ছাড়, যা আইটেম তালিকায় ওই পণ্যের নিচে ছাপা হয়।',

