'Receipt_Font_Family_Desc' => 'মুদ্রিত রসিদের সব লেখায় ব্যবহৃত ফন্ট। "ডিফল্ট" নির্বাচন করলে স্ট্যান্ডার্ড রসিদ ফন্টই থাকে।',
'Receipt_Font_Size' => 'রসিদের ফন্ট সাইজ (px)',
'Receipt_Font_Size_Desc' => 'পুরো রসিদজুড়ে লেখার আকার, 8 থেকে 24 পিক্সেল। ডিফল্ট আকার রাখতে ফাঁকা রাখুন।',
