'Amount_Paid_Help' => 'এই ডকুমেন্টে প্রয়োগ করা পরিমাণ; এটি অবশিষ্ট বাকি কমায়।',
'Received_Amount_Help' => 'বাস্তবে হাতে নেওয়া নগদ। পরিশোধিত পরিমাণের চেয়ে বেশি অংশ ভাংতি হিসেবে ফেরত দেওয়া হয় এবং বাকি কমায় না।',

