'Additional_Information' => 'অতিরিক্ত তথ্য',
'Warehouses_Tab_Help' => 'আপনার গুদামগুলো (স্টোর/শাখা) পরিচালনা করুন। প্রতিটি গুদামের নিজস্ব স্টক থাকে, এবং প্রতিটি ডকুমেন্ট — বিক্রয়, ক্রয়, স্থানান্তর, সমন্বয় — কোনো একটি গুদামের বিপরীতে রেকর্ড হয়।',
'Warehouse_Locations_Tab_Help' => 'প্রতিটি গুদামের ভেতরে র‍্যাক/শেলফ লোকেশন নির্ধারণ করুন (যেমন: আইল 2 – র‍্যাক B)। পণ্যের সঙ্গে সেগুলো যুক্ত করলে বোঝা যায় জিনিসপত্র কোথায় রাখা আছে।',
'Already_Converted' => 'বিক্রয়ে রূপান্তরিত',
'Salesperson' => 'বিক্রয় প্রতিনিধি',
'Select_Salesperson' => 'বিক্রয় প্রতিনিধি নির্বাচন করুন',
'You' => 'আপনি',
'Enable_Pos_Salesperson_Switch' => 'চেকআউটের সময় বিক্রয় প্রতিনিধি পরিবর্তন',
'Enable_Pos_Salesperson_Switch_Hint' => 'POS স্ক্রিনে একটি বিক্রয় প্রতিনিধি বাছাইকারী দেখায়, যাতে লগআউট না করেই একটি বিক্রয় অন্য কর্মীর নামে ধরা যায়। নির্বাচিত প্রতিনিধি ইনভয়েসে সংরক্ষিত হয় এবং বিক্রয় রিপোর্টে ব্যবহৃত হয়; সক্রিয় POS সেশন অপরিবর্তিত থাকে।',

'Wallet_Payment_Method_Missing' => 'ওয়ালেট পেমেন্ট পদ্ধতি পাওয়া যায়নি',
'Wallet_Payment_Method_Missing_Help' => 'ঠিক "Wallet" নামের কোনো পেমেন্ট পদ্ধতি পাওয়া যায়নি। POS-এর ওয়ালেট পেমেন্ট এই নাম দিয়ে মেলানো হয়, তাই এখানে "Wallet" নামে একটি পেমেন্ট পদ্ধতি যোগ না করা পর্যন্ত গ্রাহকরা ওয়ালেট দিয়ে পরিশোধ করতে পারবেন না:',

'Show_Previous_Dues_Line' => 'পূর্বের বকেয়ার লাইন দেখান',
'Show_Previous_Dues_Line_Desc' => 'এই বিক্রয়ের আগে গ্রাহকের কাছে পাওনা ব্যালেন্স। শূন্যের বেশি হলেই কেবল প্রিন্ট হয়।',
'Show_Net_Balance_Line' => 'নিট ব্যালেন্সের লাইন দেখান',
'Show_Net_Balance_Line_Desc' => 'পূর্বের বকেয়া এবং এই বিক্রয়ের এখনও বাকি পাওনার যোগফল। পূর্বের বকেয়া শূন্যের বেশি হলেই কেবল প্রিন্ট হয়।',

'QZ_Tray_Printer' => 'QZ Tray (এই কম্পিউটারের প্রিন্টার)',
'QZ_Printer_Name_Hint' => 'QZ Tray চালিত কম্পিউটারে প্রিন্টারের নাম যেভাবে দেখায়। সেই কম্পিউটারের ডিফল্ট প্রিন্টার ব্যবহার করতে খালি রাখুন। প্রিন্টার শনাক্ত করতে ⟳ ক্লিক করুন।',
'QZ_Not_Running' => 'এই কম্পিউটারে QZ Tray চালু নেই। qz.io থেকে ইনস্টল করে চালু রাখুন, তারপর QZ অনুমতি চাইলে এই ওয়েবসাইটকে অনুমতি দিন।',
'Detect_Printers' => 'প্রিন্টার শনাক্ত করুন',
'QZ_Download_Cert' => 'সার্টিফিকেট ডাউনলোড করুন (override.crt)',
'QZ_Setup_Title' => 'QZ Tray দিয়ে প্রিন্টিং সেটআপ করার নিয়ম (একবার, লেবেল প্রিন্ট করা প্রতিটি কম্পিউটারে)',
'QZ_Step_Install' => '১. এই কম্পিউটারে QZ Tray ইনস্টল করুন — qz.io থেকে বিনামূল্যে ডাউনলোড করুন, তারপর চালু করে চালু রাখুন (উইন্ডোজে সিস্টেম ট্রেতে বা macOS-এ মেনু বারে থাকে)।',
'QZ_Step_Connect' => '২. USB দিয়ে লেবেল প্রিন্টার সংযুক্ত করুন এবং অপারেটিং সিস্টেমে এটি ইনস্টল আছে কি না দেখুন (উইন্ডোজ: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners)।',
'QZ_Step_Detect' => '৩. এই কম্পিউটারের প্রিন্টার শনাক্ত করতে উপরের "প্রিন্টারের নাম"-এর পাশের ⟳ বোতামে ক্লিক করুন, তারপর আপনার লেবেল প্রিন্টার বেছে নিন। কম্পিউটারের ডিফল্ট প্রিন্টার ব্যবহার করতে ঘরটি খালি রাখুন।',
'QZ_Step_Cert' => '৪. অনুমতির পপআপ ছাড়া প্রিন্ট করতে নিচের সার্টিফিকেটটি ডাউনলোড করে QZ Tray ইনস্টলেশন ফোল্ডারে override.crt নামে কপি করুন (উইন্ডোজ: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — লিনাক্স: /opt/qz-tray)। তারপর QZ Tray বন্ধ করে আবার চালু করুন।',
'QZ_Step_Test' => '৫. নিচের "টেস্ট লেবেল প্রিন্ট করুন"-এ ক্লিক করুন। QZ Tray অনুমতি চাইলে Allow ক্লিক করুন — সার্টিফিকেট ইনস্টল থাকলে আর চাইবে না।',
'QZ_Step_Save' => '৬. এই সেটিংস সংরক্ষণ করতে "জমা দিন" ক্লিক করুন। বারকোড প্রিন্ট পেজের লেবেলগুলো এখন ব্রাউজারের প্রিন্ট ডায়ালগ ছাড়াই সরাসরি এই প্রিন্টারে প্রিন্ট হবে।',
'QZ_Setup_Note' => 'QZ Tray আপনি যে কম্পিউটার থেকে ব্রাউজ করছেন সেখানে চলে, তাই Stocky দূরবর্তী সার্ভারে হোস্ট থাকলেও এটি কাজ করে। লেবেল প্রিন্ট করা প্রতিটি কম্পিউটারে QZ Tray ইনস্টল থাকতে হবে।',

// PWA settings tab — installable app identity
'PWA_Enabled' => 'ইনস্টলযোগ্য অ্যাপ চালু করুন',
'PWA_Enabled_Help' => 'ব্রাউজারকে ফোন, ট্যাবলেট ও ডেস্কটপে এই অ্যাপ ইনস্টলের প্রস্তাব দিতে দেয় এবং অফলাইন পেজ ক্যাশে রাখে। বন্ধ করলে সব জায়গা থেকে ইনস্টল প্রম্পট সরে যায় এবং পরবর্তী ভিজিটে ক্যাশ মুছে যায়।',
'PWA_Identity' => 'অ্যাপের পরিচিতি',
'PWA_Launch' => 'চালু হওয়া ও চেহারা',
'PWA_App_Name' => 'অ্যাপের নাম',
'PWA_App_Name_Help' => 'ইনস্টল প্রম্পটে ও অ্যাপ তালিকায় দেখায়। Appearance সেটিংসের অ্যাপ নাম ব্যবহার করতে খালি রাখুন।',
'PWA_Short_Name' => 'সংক্ষিপ্ত নাম',
'PWA_Short_Name_Help' => 'হোম স্ক্রিনে আইকনের নিচে দেখায়, যেখানে লম্বা নাম কেটে যায়। অ্যাপ নামের "|"-এর আগের অংশ ব্যবহার করতে খালি রাখুন।',
'PWA_Description' => 'বিবরণ',
'PWA_Description_Help' => 'কিছু অ্যাপ স্টোর ও ইনস্টল ডায়ালগে দেখায়।',
