'Enable_Wholesale_Pricing' => 'পরিমাণ অনুযায়ী পাইকারি মূল্য',
'Enable_Wholesale_Pricing_Hint' => 'পণ্যে পরিমাণের ধাপ (১০-১৯ পিস, ২০-৪৯ পিস, ১০০+ ...) রাখতে দেয়, যা অর্ডারের পরিমাণ কোনো ধাপে পৌঁছালে POS ও অনলাইন স্টোরে স্বয়ংক্রিয়ভাবে খুচরা মূল্যের জায়গা নেয়। বন্ধ করলে সবকিছু আবার সাধারণ খুচরা মূল্যে বিক্রি হয় — নির্ধারিত ধাপগুলো থাকে, শুধু প্রয়োগ হয় না।',
'Wholesale_Pricing_By_Quantity' => 'পরিমাণ অনুযায়ী পাইকারি মূল্য',
'Wholesale_Pricing_By_Quantity_Hint' => 'অর্ডারের পরিমাণ কোনো ধাপে পৌঁছালে প্রতি পিসের মূল্য। উন্মুক্ত সর্বোচ্চ ধাপের জন্য (যেমন ১০০ ও তার বেশি) সর্বোচ্চ খালি রাখুন। প্রথম ধাপের নিচে পণ্য সাধারণ খুচরা মূল্যে বিক্রি হয়।',
'Wholesale_Pricing_Variants_Hint' => 'একটি ধাপ-তালিকা পুরো পণ্যকে কভার করে: প্রতিটি ভ্যারিয়েন্ট নিজের লাইন কোনো ধাপে পৌঁছালে সেই ধাপের মূল্যে বিক্রি হয়।',
