/* ---- Online orders guide (Store > Online Orders) ---- */
'Orders_Guide' => 'অর্ডার গাইড',
'Ord_Guide_Intro' => 'আপনার অনলাইন স্টোরে দেওয়া অর্ডার কীভাবে আপনার স্টক ও হিসাবে যায়, এবং টাকা আসলে কোথায় রেকর্ড হয়।',
'Ord_Guide_Lifecycle_Title' => 'অর্ডারের অবস্থা',
'Ord_Guide_Lifecycle_Pending' => 'আপনার পর্যালোচনার অপেক্ষায় থাকা নতুন অর্ডার। শুধু অপেক্ষমাণ অর্ডারই নিশ্চিত বা বাতিল করা যায়।',
'Ord_Guide_Lifecycle_Confirmed' => 'আপনি অর্ডারটি গ্রহণ করেছেন। Stocky আপনার বেছে নেওয়া গুদামে একটি বিক্রয় তৈরি করে ও স্টক কেটে নেয় — সেই বিক্রয়ই আপনার স্টক, পেমেন্ট ও লাভের রিপোর্টের রেকর্ড।',
'Ord_Guide_Lifecycle_Shipped' => 'আপনি অর্ডারটি পাঠিয়েছেন। শুধু পূরণের ধাপ: নিশ্চিত করার সময়ই স্টক কাটা হয়েছিল।',
'Ord_Guide_Lifecycle_Delivered' => 'গ্রাহক অর্ডারটি পেয়েছেন। এখান থেকেই ফেরতের সময়সীমা শুরু হয়।',
'Ord_Guide_Lifecycle_Cancelled' => 'নিশ্চিত করার আগেই অর্ডারটি বাদ দেওয়া হয়েছে, তাই কোনো বিক্রয় তৈরি হয়নি ও কোনো স্টক কাটা হয়নি।',
'Ord_Guide_PaymentStatus_Tip' => 'চেকআউটে নির্ধারিত হয় ও এখানে সম্পাদনাযোগ্য নয়। পেমেন্ট কীভাবে রেকর্ড করবেন দেখতে ক্লিক করুন।',
'Ord_Guide_Payment_Title' => 'পেমেন্টের অবস্থা',
'Ord_Guide_Payment_Intro' => 'এই কলামে গ্রাহক চেকআউটে কীভাবে পরিশোধ করতে চেয়েছেন তা রেকর্ড থাকে। এটি স্টোরফ্রন্ট নির্ধারণ করে এবং এই পেজ থেকে সম্পাদনা করা যায় না — টাকা নিজে ট্র্যাক হয় সেই বিক্রয়ে, যা অর্ডার নিশ্চিত করলে তৈরি হয়।',
'Ord_Guide_Payment_Paid' => 'গ্রাহক পেমেন্ট গেটওয়ের মাধ্যমে অনলাইনে আগেই পরিশোধ করেছেন। অর্ডার নিশ্চিত করলে বিক্রয়টি Paid হিসেবে তৈরি হয় এবং পেমেন্ট আপনার জন্য রেকর্ড হয়ে যায় — আর কিছু করার নেই।',
'Ord_Guide_Payment_Pending' => 'ক্যাশ অন ডেলিভারি, ব্যাংক ট্রান্সফার বা অন্য কোনো পরে-পরিশোধ পদ্ধতি। অর্ডার নিশ্চিত করলে বিক্রয়টি Unpaid হিসেবে তৈরি হয়, তাই টাকা পাওয়ার পর নিজেই রেকর্ড করুন — নিচের ধাপগুলো দেখুন।',
'Ord_Guide_Payment_Failed' => 'গেটওয়ে পেমেন্ট প্রত্যাখ্যান করেছে বা গ্রাহক মাঝপথে ছেড়ে দিয়েছেন। অর্ডারটি স্বয়ংক্রিয়ভাবে বাতিল হয়।',
'Ord_Guide_MarkPaid_Title' => 'পেমেন্ট pending থেকে paid-এ পরিবর্তন',
'Ord_Guide_MarkPaid_Step1' => 'প্রথমে এখানে অর্ডার নিশ্চিত করুন — নিশ্চিত করলেই বিক্রয় তৈরি হয়।',
'Ord_Guide_MarkPaid_Step2' => 'Sales > All Sales খুলে সেই বিক্রয়টি খুঁজুন (একই গ্রাহক, এবং বিবরণ পেজে দেখায় এটি কোন অনলাইন অর্ডার থেকে এসেছে)।',
'Ord_Guide_MarkPaid_Step3' => 'সারির অ্যাকশন মেনু খুলে Create Payment বেছে নিন।',
'Ord_Guide_MarkPaid_Step4' => 'পরিমাণ, পেমেন্ট পদ্ধতি ও তারিখ লিখে সংরক্ষণ করুন। পরিমাণ অনুযায়ী বিক্রয়টি নিজে থেকেই Partial বা Paid-এ চলে যায়।',
'Ord_Guide_MarkPaid_Note' => 'এখানে দেখানো পেমেন্টের অবস্থা চেকআউটের পছন্দ রেকর্ড করে রাখে এবং যেমন আছে তেমনই থাকে। বিক্রয়ই হিসাবের রেকর্ড, এবং সেটিই আপনার পেমেন্ট ও লাভের রিপোর্টে যায়। আপনি যা লিখেছেন তা পর্যালোচনা বা সম্পাদনা করতে বিক্রয়ে Show Payments ব্যবহার করুন।',
'Ord_Guide_Notes_Title' => 'জেনে রাখা ভালো',
'Ord_Guide_Note_Warehouse' => 'নিশ্চিত করার সময় আপনি যে গুদাম বেছে নেন তা ঠিক করে স্টক কোথা থেকে নেওয়া হবে। যেসব গুদাম পুরো অর্ডার কভার করতে পারে না সেগুলো ওই তালিকায় Out of Stock চিহ্নিত থাকে।',
'Ord_Guide_Note_Preorder' => 'প্রি-অর্ডার আইটেম স্টক চেক এড়িয়ে যায়, তাই সেগুলো থাকা অর্ডার পরিমাণ হাতে না থাকলেও নিশ্চিত করা যায়।',
'Ord_Guide_Note_Flagged' => 'Flagged ট্যাগ মানে অর্ডারটি চেকআউটে জালিয়াতি পরীক্ষায় ধরা পড়েছে। কারণ দেখতে ট্যাগের উপর হোভার করুন এবং নিশ্চিত করার আগে অর্ডারটি পর্যালোচনা করুন।',
'Ord_Guide_Note_Cancel' => 'অর্ডার অপেক্ষমাণ থাকা পর্যন্তই শুধু বাতিল করা যায়। নিশ্চিত হয়ে গেলে বিক্রয় বা গ্রাহক ফেরতের মাধ্যমে এটি উল্টে দিন।',


