// Variants guide drawer (product form).
'Guide' => 'নির্দেশিকা',
'Variants_Guide' => 'ভ্যারিয়েন্ট নির্দেশিকা',
'VG_Intro' => 'একটি ভেরিয়েবল পণ্য কয়েকটি ভ্যারিয়েন্ট হিসেবে বিক্রি হয়। এগুলো অপশন থেকে (প্রস্তাবিত) অথবা নামের একটি সাধারণ তালিকা হিসেবে তৈরি করুন। প্রতিটি ভ্যারিয়েন্টের নিজস্ব কোড, মূল্য, ছবি ও স্টক থাকে।',
'VG_Options_Title' => 'অপশন মোড (রঙ, সাইজ...)',
'VG_Opt_Step1' => 'কার্ড হেডারের সুইচটি "অপশন"-এ রাখুন।',
'VG_Opt_Step2' => 'রঙ বা সাইজের মতো একটি অপশনের নাম লিখুন, অথবা প্রস্তাবনাগুলো থেকে একটি বেছে নিন।',
'VG_Opt_Step3' => 'একটি মান লিখুন (যেমন লাল) এবং Enter চাপুন। প্রতিটি মানের জন্য পুনরাবৃত্তি করুন; কমা দিয়েও মান আলাদা করা যায়। কোনো মান সরাতে তার x-এ ক্লিক করুন।',
'VG_Opt_Step4' => 'দ্বিতীয় বা তৃতীয় অপশনের জন্য "অপশন যোগ করুন"-এ ক্লিক করুন (সর্বোচ্চ ৩টি অপশন)।',
'VG_Opt_Step5' => '"ভ্যারিয়েন্ট তৈরি করুন"-এ ক্লিক করুন। প্রতিটি সমন্বয়ের জন্য একটি সারি তৈরি হয় এবং এর নাম স্বয়ংক্রিয়ভাবে তৈরি হয়, যেমন "Red / S"।',
'VG_Opt_Step6' => 'প্রতিটি সারিতে খরচ ও মূল্য লিখুন, অথবা "সবগুলোতে প্রয়োগ করুন"-এ একটি মান লিখে খরচ বা মূল্যে ক্লিক করে সেটি প্রতিটি সারিতে কপি করুন।',
'VG_Opt_Step7' => 'কোডগুলো আপনার জন্য তৈরি হয়। নিজের কোড লিখুন অথবা আরেকটি তৈরি করতে রিফ্রেশ আইকনে ক্লিক করুন।',
'VG_Opt_Step8' => 'ঐচ্ছিক: কোনো অপশনে "রঙের সোয়াচ" টিক দিন এবং প্রতিটি মানের জন্য একটি রঙ বেছে নিন; স্টোর এটিকে একটি রঙিন বিন্দু হিসেবে দেখায়।',
'VG_Rows_Title' => 'ভ্যারিয়েন্টের সারি',
'VG_Rows_Text' => 'প্রতিটি সারিতে একটি ছবি, কোড, বারকোড, খরচ, মূল্য, পাইকারি মূল্য ও সর্বনিম্ন বিক্রয় মূল্য থাকে। পণ্য তৈরির সময় আপনি প্রতিটি ভ্যারিয়েন্টের জন্য গুদামভিত্তিক প্রারম্ভিক স্টকও লিখতে পারেন। "অসম্পূর্ণ" ট্যাগের অর্থ সারিটিতে কোনো একটি অপশনের মান নেই।',
'VG_List_Title' => 'সাধারণ তালিকা মোড',
'VG_List_Text' => 'একটি সারি যোগ করতে ভ্যারিয়েন্টের নাম লিখে Enter চাপুন (অথবা যোগ করুন-এ ক্লিক করুন), তারপর এর কোড ও মূল্য পূরণ করুন। এটি ক্লাসিক আচরণ এবং বিদ্যমান পণ্যগুলোর জন্য উপলব্ধ থাকে।',
'VG_Edit_Title' => 'পরে সম্পাদনা',
'VG_Edit_1' => 'একটি মান যোগ করে "ভ্যারিয়েন্ট তৈরি করুন"-এ ক্লিক করুন: শুধু অনুপস্থিত সমন্বয়গুলো যোগ হয়। বিদ্যমান সারিগুলো তাদের কোড, মূল্য ও ইতিহাস বজায় রাখে।',
'VG_Edit_2' => 'কোনো মান বা অপশন সরালে সেটি ব্যবহারকারী সারিগুলো সরে যায়। ইতিমধ্যে সংরক্ষিত সারিগুলো নিশ্চিতকরণের পর পণ্য সংরক্ষণ করলে মুছে যায়।',
'VG_Edit_3' => 'যে ভ্যারিয়েন্টে এখনও স্টক আছে তা সরানো যাবে না। আগে এর স্টক সমন্বয় বা স্থানান্তর করুন।',
'VG_Edit_4' => '"সাধারণ তালিকা"-এ গেলে সারি ও তাদের নাম থাকে কিন্তু অপশনের সংজ্ঞাগুলো বাদ যায়।',
'VG_Store_Title' => 'অনলাইন স্টোরে',
'VG_Store_Text' => 'গ্রাহকরা প্রতিটি অপশন থেকে একটি মান বেছে নেন, যেমন প্রথমে রঙ তারপর সাইজ। যে সমন্বয়গুলো নেই সেগুলো নিষ্ক্রিয় থাকে এবং স্টক শেষ হওয়াগুলো কেটে দেখানো হয়। বেছে নেওয়া ভ্যারিয়েন্টটিই কার্টে যায়।',
'Choose_Source' => 'উৎস নির্বাচন করুন',
'Portal_Request' => 'পোর্টাল অনুরোধ',
