'Warehouse_Invoice_Address_Help' => 'এই গুদাম থেকে ইস্যু করা ইনভয়েসে মুদ্রিত রাস্তার ঠিকানা। সেটিংসের কোম্পানির ঠিকানা ব্যবহার করতে ফাঁকা রাখুন।',
'Warehouse_Logo_Help' => 'এই গুদামের ইনভয়েস ও POS রসিদে মুদ্রিত লোগো। কোম্পানির লোগো ব্যবহার করতে ফাঁকা রাখুন।',
'Warehouse_Invoice_Footer_Help' => 'এই গুদাম থেকে ইস্যু করা ইনভয়েসের নিচে মুদ্রিত অতিরিক্ত নোট।',
'Issued_By' => 'ইস্যুকারী',
'Enable_Warehouse_Letterhead' => 'ইনভয়েসে গুদামের লেটারহেড',
'Enable_Warehouse_Letterhead_Hint' => 'ইনভয়েস, POS রসিদ ও পাবলিক ইনভয়েস পেজে ইস্যুকারী গুদাম মুদ্রণ করুন: এর নাম কোম্পানির নামের জায়গায় বসে, এবং এর ঠিকানা, ফোন, ইমেইল, লোগো ও ফুটার নোট কোম্পানির তথ্যের জায়গায় বসে। গুদামে কোনো ফিল্ড ফাঁকা থাকলে সেটি গ্লোবাল কোম্পানি সেটিংস থেকে নেওয়া হয়।',
'Warehouse_Letterhead_Receipt_Notice' => 'গুদামের লেটারহেড চালু আছে: প্রকৃত রসিদে মুদ্রিত স্টোরের নাম, ঠিকানা ও ফোন বিক্রয়টি ইস্যুকারী গুদাম থেকে নেওয়া হয়, এবং এর ফুটার নোট গ্রাহক নোটের নিচে যোগ হয়।',
'Warehouse_Letterhead_Receipt_Demo' => 'শাখার ফুটার নোট — গুদাম অংশে প্রতিটি গুদামের জন্য সেট করুন।',
'Asked_By' => 'প্রশ্নকারী',
'Account_Ledger' => 'অ্যাকাউন্ট লেজার',
'Closing_Balance' => 'সমাপনী ব্যালেন্স',
'Shopify_Link_Card_Hint' => 'এই পণ্যটিকে আপনার শপে ইতিমধ্যে বিদ্যমান একটি লিস্টিংয়ের সাথে যুক্ত করুন, যাতে সিঙ্ক দ্বিতীয় একটি তৈরি না করে সেটিকেই আপডেট করে।',
'Shopify_Not_Linked' => 'লিঙ্ক করা নেই। পণ্য পুশ করলে এই শপে একটি নতুন লিস্টিং তৈরি হবে।',
