'Upd_Manual_Step_Done' => 'সম্পন্ন! আপডেট করা অ্যাপ্লিকেশন উপভোগ করুন।',
'Upd_Note_Blank_Pages' => 'নোট: কোনো পৃষ্ঠা লোড না হলে বা ফাঁকা দেখালে, নিশ্চিত করুন যে আপনি ব্রাউজারের ক্যাশ পরিষ্কার করেছেন।',
'Upd_Guide_Before_Title' => '১. আপডেটের আগে',
'Upd_Guide_Before_Download' => 'আপনার CodeCanyon অ্যাকাউন্ট ({path}) থেকে অ্যাপ্লিকেশনের {package} ডাউনলোড করুন। এটি এক্সট্র্যাক্ট করবেন না — আপডেটারের জন্য ZIP ফাইলটি ঠিক ডাউনলোড করা অবস্থায় প্রয়োজন।',
'Upd_Latest_Full_Zip' => 'সর্বশেষ পূর্ণ ZIP প্যাকেজ',
'Upd_Guide_Before_Admin' => 'নিশ্চিত করুন যে আপনি {perm} পারমিশনধারী একজন অ্যাডমিনিস্ট্রেটর হিসেবে লগইন করেছেন। অন্য কেউ আপডেটার দেখতে বা চালাতে পারেন না।',
'Upd_Guide_Before_Quiet' => 'একটি নিরিবিলি সময় বেছে নিন: আপডেটের সময় অ্যাপ্লিকেশনটি অল্প সময়ের জন্য মেইনটেন্যান্স মোডে চলে যায় এবং অন্যান্য ব্যবহারকারীরা প্রবেশ করতে পারেন না।',
'Upd_Guide_Before_No_Manual' => 'আপনাকে ম্যানুয়ালি ব্যাকআপ নেওয়া, ফাইল এক্সট্র্যাক্ট করা, কমান্ড চালানো, কনফিগারেশন ফাইল সম্পাদনা করা বা ডেটাবেসে হাত দেওয়ার প্রয়োজন {not} — আপডেটার এই সবকিছু স্বয়ংক্রিয়ভাবে করে। (অবশ্য একটি অতিরিক্ত ম্যানুয়াল ব্যাকআপে কোনো ক্ষতি নেই।)',
'Upd_Not' => 'নেই',
'Upd_Guide_Code_Overwritten' => 'আপনি যদি অ্যাপ্লিকেশনের কোড ম্যানুয়ালি পরিবর্তন করে থাকেন, তবে আপডেটে আপনার পরিবর্তনগুলো ওভাররাইট হয়ে যাবে। আপনার ডেটা, আপলোড, সেটিংস ও .env সবসময় সংরক্ষিত থাকে।',
'Upd_Guide_Running_Title' => '২. আপডেট চালানো',
'Upd_Guide_Run_Open' => '{path} (এই পৃষ্ঠা) খুলুন এবং {tab} ট্যাবে থাকুন।',
'Upd_Guide_Run_Upload' => '{upload}: ডাউনলোড করা প্যাকেজটি আপলোড বক্সে ক্লিক করে বা টেনে আনুন। বড় ফাইলগুলো ছোট ছোট অংশে আপলোড হয়, তাই কম আপলোড সীমাসহ শেয়ার্ড হোস্টিংয়েও এটি কাজ করে। একটি চেকসাম ক্ষতিগ্রস্ত বা অসম্পূর্ণ আপলোড থেকে সুরক্ষা দেয়।',
'Upd_Upload_The_Zip' => 'ZIP আপলোড করুন',
'Upd_Guide_Run_Validation' => 'আপলোডের পর {auto} (আপনি {button} বাটন দিয়ে এটি পুনরায় চালাতে পারেন)। সিস্টেম যাচাই করে: ZIP-এর অখণ্ডতা, প্যাকেজের কাঠামো ও সম্পূর্ণতা, সংস্করণের সামঞ্জস্যতা (ডাউনগ্রেড প্রত্যাখ্যাত হয়), প্রয়োজনীয় PHP সংস্করণ ও এক্সটেনশন, ফাইল পারমিশন, খালি ডিস্ক স্পেস, ডেটাবেস সংযোগ, কনফিগারেশন, এবং অন্য কোনো আপডেট চলছে না কিনা।',
'Upd_Validation_Runs_Automatically' => 'যাচাই স্বয়ংক্রিয়ভাবে চলে',
'Upd_Guide_Run_Review' => '{panel} প্যানেলটি পর্যালোচনা করুন। {button} বাটনটি শুধু তখনই দেখা যায় যখন প্রতিটি গুরুত্বপূর্ণ যাচাই সফল হয়। কোনো যাচাই ব্যর্থ হলে, বার্তাটি ঠিক কী সমাধান করতে হবে তা জানায়।',
'Upd_Guide_Run_Click' => '{button} ক্লিক করে নিশ্চিত করুন। তারপর শুধু {keep} এবং অগ্রগতি রেল দেখুন। সিস্টেম ক্রমানুসারে সম্পাদন করে:',
'Upd_Keep_Page_Open' => 'এই পৃষ্ঠাটি খোলা রাখুন',
'Upd_Guide_Phase_Backup' => '{label} — একটি পূর্ণ ডেটাবেস ডাম্প, আপডেট পরিবর্তন করতে পারে এমন প্রতিটি অ্যাপ্লিকেশন ফাইলের একটি ZIP, এবং {env}-এর একটি কপি তৈরি ও {verified} করা হয়। আপনার আপলোড ({images}) এবং {storage} কখনো আপডেটে স্পর্শ করা হয় না, তাই এগুলো আর্কাইভ করা হয় না। ব্যাকআপ তৈরি করা না গেলে, আপডেট এখানেই থেমে যায় এবং কিছুই পরিবর্তন হয় না।',
'Upd_Verified' => 'যাচাই',
'Upd_Guide_Phase_Prepare' => '{label} — নতুন সংস্করণটি একটি স্টেজিং এলাকায় এক্সট্র্যাক্ট করে আবার যাচাই করা হয়। লাইভ অ্যাপ্লিকেশন তখনো অক্ষত থাকে।',
'Upd_Guide_Phase_Maintenance' => '{label} — মেইনটেন্যান্স মোড সক্রিয় হয়; ভিজিটররা একটি বন্ধুত্বপূর্ণ "আমরা শীঘ্রই ফিরে আসছি" স্ক্রিন দেখেন।',
'Upd_Guide_Phase_Files' => '{label} — নতুন ফাইলগুলো প্রায় তাৎক্ষণিকভাবে প্রতিস্থাপিত হয়; পুরোনো ফাইলগুলো রোলব্যাকের জন্য আলাদা রাখা হয়। সুরক্ষিত পাথ ({env}, {storage}, {images}) কখনো প্রতিস্থাপিত হয় না।',
'Upd_Guide_Phase_Database' => '{label} — মাইগ্রেশন চলে, তারপর পারমিশন, অনুবাদ ও টেমপ্লেট রিফ্রেশ করা হয়।',
'Upd_Guide_Phase_Cache' => '{label} — সব ক্যাশ পরিষ্কার করে পুনর্গঠন করা হয়।',
'Upd_Guide_Phase_Verify' => '{label} — হেলথ চেক নিশ্চিত করে যে নতুন সংস্করণ চালু হয়, ডেটাবেস কাজ করে, সব মাইগ্রেশন চলেছে এবং কনফিগারেশন বৈধ।',
'Upd_Guide_Phase_Done' => '{label} — মেইনটেন্যান্স মোড তুলে নেওয়া হয় এবং অস্থায়ী ফাইলগুলো পরিষ্কার করা হয়।',
'Upd_Guide_Run_Success' => 'যখন আপনি {success} দেখবেন, {reload} ক্লিক করুন এবং আপনার ব্রাউজার হার্ড-রিফ্রেশ করুন ({keys}) যাতে নতুন অ্যাডমিন প্যানেলের অ্যাসেট লোড হয়।',
'Upd_Update_Successful_Short' => 'আপডেট সফল',
'Upd_Guide_No_Internet' => 'আপডেটের সময় কোনো ইন্টারনেট সংযোগের প্রয়োজন নেই — সবকিছু আপলোড করা ZIP থেকে আসে। সংযোগ বিচ্ছিন্ন হলে বা ব্রাউজার বন্ধ করলেও আপডেট নষ্ট হয় না: সার্ভার ঠিক কোথায় থেমেছিল তা মনে রাখে।',
'Upd_Guide_Wrong_Title' => '৩. কিছু ভুল হলে',
'Upd_Guide_Wrong_Rollback' => '{label} — ফাইল পরিবর্তন শুরু হওয়ার পর কিছু ব্যর্থ হলে (এক্সট্র্যাকশন ত্রুটি, মাইগ্রেশন ব্যর্থতা, হেলথ চেক ব্যর্থতা, ডিস্ক পূর্ণ, …), সিস্টেম স্বয়ংক্রিয়ভাবে যাচাইকৃত ব্যাকআপ থেকে পূর্ববর্তী ফাইল ও ডেটাবেস পুনরুদ্ধার করে, মেইনটেন্যান্স মোড তুলে নেয় এবং {message} রিপোর্ট করে। আপনি ঠিক যেখান থেকে শুরু করেছিলেন সেখানেই ফিরে আসেন।',
'Upd_Automatic_Rollback' => 'স্বয়ংক্রিয় রোলব্যাক',
'Upd_Failed_Previous_Restored' => 'আপডেট ব্যর্থ — পূর্ববর্তী সংস্করণ পুনরুদ্ধার করা হয়েছে',
'Upd_Guide_Wrong_Interrupted' => '{label} (সার্ভার রিস্টার্ট, টাইমআউট, ব্রাউজার বন্ধ, বিদ্যুৎ বিভ্রাট) — এই পৃষ্ঠাটি আবার খুললে, একটি লাল ব্যানার দুটি নিরাপদ বিকল্প দেয়: {resume} (ঠিক যে ধাপে থেমেছিল সেখান থেকে আবার শুরু করে) অথবা {rollback} (ব্যাকআপ থেকে পূর্ববর্তী সংস্করণ পুনরুদ্ধার করে)।',
'Upd_Interrupted_Update' => 'বাধাপ্রাপ্ত আপডেট',
'Upd_Guide_Wrong_Unreachable' => '{label} — {path}-এ স্বতন্ত্র {console} ব্যবহার করুন। সাইট মেইনটেন্যান্স মোডে থাকলে বা অ্যাডমিন প্যানেলের অ্যাসেট নষ্ট হলেও এটি কাজ করে এবং একই চালিয়ে যান / রোল ব্যাক অপশন দেয়। মেইনটেন্যান্স স্ক্রিনের নিচে একটি অপ্রকাশ্য "অ্যাডমিনিস্ট্রেটর অ্যাক্সেস" লিংকও রয়েছে।',
'Upd_Admin_Unreachable' => 'অ্যাডমিন প্যানেলে পৌঁছানো যাচ্ছে না',
'Upd_Recovery_Console' => 'রিকভারি কনসোল',
'Upd_Guide_Wrong_Locked_Out' => '{label} — আপডেট চলাকালীন এই পৃষ্ঠাটি একটি {link} দেখায়। আবার প্রবেশ করার প্রয়োজন হলে (যেমন আপনার সেশনের মেয়াদ শেষ হওয়ার পর) এটি সংরক্ষণ করুন; এটি আপনাকে মেইনটেন্যান্স স্ক্রিন অতিক্রম করতে দেয় যাতে আপনি আবার লগইন করতে পারেন।',
'Upd_Locked_Out_Maintenance' => 'মেইনটেন্যান্স মোডের কারণে প্রবেশ বন্ধ',
'Upd_Bypass_Link' => 'বাইপাস লিংক',
'Upd_Guide_Wrong_Concurrent' => '{label} — তারা {message} দেখবেন। একসাথে কখনো শুধু একটি আপডেটই চলতে পারে।',
'Upd_Another_Admin_Updating' => 'অন্য একজন অ্যাডমিন একই সময়ে আপডেট করার চেষ্টা করছেন',
'Upd_Guide_Backups_Title' => '৪. ব্যাকআপ ও পুনরুদ্ধার',
'Upd_Guide_Backups_Created' => 'প্রতিটি আপডেট কোনো কিছুতে হাত দেওয়ার {before} একটি ব্যাকআপ তৈরি করে: আপডেট প্রতিস্থাপন করতে পারে এমন সব অ্যাপ্লিকেশন ফাইল, {env}-এর একটি কপি এবং একটি পূর্ণ ডেটাবেস ডাম্প। আপলোড ও {storage} কখনো আপডেটে পরিবর্তিত হয় না এবং তাই এর অংশ নয় — এগুলোর নিজস্ব ব্যাকআপ রাখুন। ব্যাকআপগুলো {path}-এ থাকে এবং কখনো ওয়েব থেকে অ্যাক্সেসযোগ্য নয়।',
'Upd_Before' => 'আগে',
'Upd_Guide_Backups_Panel' => '{tab} ট্যাবের {panel} প্যানেলে তারিখ, সংস্করণ ও আকার সহ এগুলোর তালিকা থাকে। সেখান থেকে আপনি যেকোনো সম্পূর্ণ ব্যাকআপ {restore} করতে পারেন (ফাইল + ডেটাবেস — প্রথমে বর্তমান ডেটাবেসের একটি নিরাপত্তা কপি নেওয়া হয়) অথবা পুরোনোগুলো {delete} করতে পারেন।',
'Upd_Restore_Verb' => 'পুনরুদ্ধার',
'Upd_Delete_Verb' => 'মুছুন',
'Upd_Guide_Backups_Retention' => 'কতগুলো ব্যাকআপ রাখা হবে তা বেছে নিতে {keep} ব্যবহার করুন; প্রতিটি সফল আপডেটের পর পুরোনোগুলো স্বয়ংক্রিয়ভাবে মুছে ফেলা হয়। শেষ অবশিষ্ট সম্পূর্ণ ব্যাকআপটি কখনো মোছা যায় না — ফেরার একটি পথ সবসময় থাকে।',
'Upd_Guide_Manual_Title' => '৫. ম্যানুয়াল আপডেট (বিকল্প পদ্ধতি)',
'Upd_Guide_Manual_Text' => 'আপনি যদি হাতে আপডেট করতে চান, অথবা আপনার সার্ভারে আপলোডার ব্যবহার করা না যায়, তাহলে এই পৃষ্ঠার {tab} ট্যাবে ধাপে ধাপে দেওয়া নির্দেশনা অনুসরণ করুন।',
'Upd_Guide_Clear_Cache_First' => 'কোনো আপডেটের পর পৃষ্ঠাগুলো ভাঙা বা ফাঁকা দেখালে প্রথমে আপনার ব্রাউজারের ক্যাশ পরিষ্কার করুন — প্রায় সবসময় এটাই কারণ।',
'Upd_Restore_Backup_Confirm' => 'এই ব্যাকআপ পুনরুদ্ধার করবেন? বর্তমান ফাইল ও বর্তমান ডাটাবেস ব্যাকআপ দিয়ে প্রতিস্থাপিত হবে। প্রথমে বর্তমান ডাটাবেসের একটি নিরাপত্তা কপি নেওয়া হয়। (v{version} — {date})',
'Woo_Guide_Lead' => 'একটি WooCommerce শপ কীভাবে ERP-এর সাথে তাল মিলিয়ে চলে। নিচের cron লাইনগুলো এই সার্ভারের জন্যই তৈরি, তাই সরাসরি কপি করে এখানে বসানো যায়।',
'Woo_Guide_Ways_Note' => 'Shopify-এর মতো নয়, WooCommerce নিজে থেকে ERP-তে কিছুই পাঠায় না — এখানে কোনো Webhook রিসিভার নেই, তাই {in} আসা সবকিছু শিডিউল অনুযায়ী আসে। শুধু {out} যাওয়া স্টক তাৎক্ষণিক হতে পারে।',
'Woo_In' => 'ভেতরে',
'Woo_Out' => 'বাইরে',
'Woo_Guide_Both_Ways_Title' => 'দুই পদ্ধতিতেই প্রথমে এটি প্রয়োজন',
'Woo_Api_Keys' => 'API কী',
'Woo_Guide_Api_Keys_Text' => '{path}, অনুমতি {perm}। কনজিউমার কী ও সিক্রেট {settings} ট্যাবে কপি করুন, সাথে স্টোর URL — শেষে স্ল্যাশ ছাড়া আপনার সাইটের ঠিকানা, যেমন {example}।',
'Woo_Credentials_Saved' => 'ক্রেডেনশিয়াল সংরক্ষিত',
'Woo_Not_Configured_Yet' => 'এখনও কনফিগার করা হয়নি',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress অ্যাপ্লিকেশন পাসওয়ার্ড (ঐচ্ছিক)',
'Woo_Guide_Wp_App_Password_Text' => 'শুধু পণ্যের ছবির জন্য ব্যবহৃত হয়। WooCommerce API পণ্য, স্টক, ক্যাটাগরি, ব্র্যান্ড, গ্রাহক ও অর্ডার আদান-প্রদান করে; WordPress API মিডিয়া লাইব্রেরিতে খোঁজে এবং সেখানে নেই এমন ছবি আপলোড করে।',
'Woo_Guide_Wp_App_Password_Note' => 'মিডিয়া পরিচালনা করতে পারেন এমন একজন WordPress ব্যবহারকারী ব্যবহার করুন, এবং {path}-এ পাসওয়ার্ডটি তৈরি করুন। দুটি ঘর ফাঁকা রাখলেও সবকিছু সিঙ্ক হবে — শুধু ছবি সংযুক্তি বাদ যাবে।',
'Woo_Guide_Pick_Way_Title' => 'তারপর বেছে নিন কীভাবে তাল মিলিয়ে চলবে',
'Woo_Right_Away' => 'সঙ্গে সঙ্গে',
'Woo_Stock_Live' => 'স্টক লাইভ',
'Woo_Stock_Not_Live' => 'স্টক লাইভ নয়',
'Woo_Guide_Realtime_Lead' => 'শুধু একদিকে: ERP থেকে বের হওয়া স্টক ও পণ্য। WooCommerce-এ করা অর্ডার ও পণ্যের পরিবর্তন এখনও শিডিউল অনুযায়ী আসে — অন্য ট্যাবটি দেখুন।',
'Woo_Push_Stock_On_Change' => 'স্টক পরিবর্তনের সঙ্গে সঙ্গে পুশ করুন',
'Woo_Setting_People_Miss' => 'এই সেটিংটিই মানুষ মিস করে',
'Woo_Guide_Pos_Sale_Not_Reach' => 'একটি POS বিক্রয় নিজে থেকে WooCommerce-এ {not}। বন্ধ রাখলে শপ শুধু পরবর্তী স্টক সিঙ্কে জানতে পারে — ডিফল্টভাবে এক ঘণ্টা — এবং সেই সময়ের মধ্যে কাউন্টারে আগেই বিক্রি হয়ে যাওয়া একটি ইউনিট শপ আবার বিক্রি করে ফেলতে পারে।',
'Woo_Does_Not' => 'পৌঁছায় না',
'Woo_Guide_Tick_Instant' => '{settings} ট্যাবে {option} টিক দিন। এটুকুই পুরো সেটআপ — কোনো worker নেই, কোনো cron নেই। এরপর প্রতিটি বিক্রয়, রিটার্ন, সমন্বয়, স্থানান্তর ও গৃহীত ক্রয় বিক্রয় সংরক্ষণের ঠিক পরেই শুধু সেই পণ্যগুলোর একটি পুশ পাঠায়, এবং বিশ লাইনের একটি বিক্রয়ে একটিই পুশ লাগে, বিশটি নয়। কাউন্টারকে কখনো এর জন্য অপেক্ষা করতে হয় না।',
'Woo_Currently' => 'বর্তমানে:',
'Woo_Instant_On_Text' => 'চালু — পরিবর্তনে স্টক পুশ হয়',
'Woo_Instant_Off_Text' => 'বন্ধ — স্টক শুধু শিডিউল অনুযায়ী',
'Woo_Guide_Instant_Note' => 'শুধু ইতিমধ্যে WooCommerce-এর সাথে লিঙ্ক করা পণ্যগুলোই পুশ হয় — যে পণ্য কখনো সিঙ্ক হয়নি, শপে তার সংশোধন করার মতো কিছু নেই। ভ্যারিয়েবল পণ্য তাদের প্যারেন্টের মাধ্যমে যায়, এবং কোনো কম্বোর যেকোনো উপাদান নড়াচড়া করলে কম্বোটি আবার পুশ হয়। বাল্ক অপারেশন (পণ্য মোছা, গুদাম রিসেট করা) কোনো ইভেন্ট ছাড়াই স্টক লেখে, যা প্রতি ঘণ্টার স্টক সিঙ্কটিও চালু রাখার একটি কারণ।',
'Woo_Push_Products_On_Save' => 'পণ্য সংরক্ষণের সঙ্গে সঙ্গে পুশ করুন',
'Woo_Guide_Tick_Auto_Products' => '{settings} ট্যাবে {option} টিক দিন, এবং Stocky-তে তৈরি, সম্পাদিত বা ডুপ্লিকেট করা পণ্য সংরক্ষণের ঠিক পরেই WooCommerce-এ পাঠানো হবে — বিবরণ, মূল্য, ভ্যারিয়েন্ট ও ছবি, তারপর তার স্টক। রাতের পণ্য সিঙ্কের অপেক্ষা না করে নতুন পণ্য সঙ্গে সঙ্গে শপে তৈরি হয়।',
'Woo_On' => 'চালু',
'Woo_Off' => 'বন্ধ',
'Woo_Guide_Bulk_Imports_Note' => 'বাল্ক ইমপোর্ট একটি একটি করে পুশ হয় না — ইমপোর্টের পর একটি পণ্য সিঙ্ক চালান। প্রথমে ক্যাটাগরি ও ব্র্যান্ড সিঙ্ক করুন, যাতে পুশ করা পণ্য সঠিক ক্যাটাগরিতে যায়।',
'Woo_Nothing_Else_To_Install' => 'আর কিছু ইনস্টল করার নেই',
'Woo_Guide_Same_Process' => 'কোনো queue worker নেই, কোনো cron এন্ট্রি নেই। পুশটি সেই একই প্রসেসে চলে যা বিক্রয়টি পরিবেশন করেছে, রেসপন্স ফেরত যাওয়ার {after}, তাই কাউন্টারকে কখনো WooCommerce-এর জন্য অপেক্ষা করতে হয় না। পুশগুলো কখনো একসাথে চলে না: একটি চলাকালীন করা পরিবর্তনগুলো সেটির জন্য অপেক্ষা করে এবং ঠিক পরেই চলে যায়।',
'Woo_After' => 'পরে',
'Woo_Guide_Shop_Stops_Answering' => 'যে শপ সাড়া দেওয়া বন্ধ করে, আট সেকেন্ড পর তার আশা ছেড়ে দেওয়া হয়, এবং পুশ পাঁচ মিনিটের জন্য বিরতি নেয় যাতে প্রতিটি বিক্রয় আবার এর জন্য অপেক্ষা না করে; এর মধ্যে আসা পরিবর্তনগুলো বিরতির পর প্রথম পুশের সাথে চলে যায়, এবং প্রতি ঘণ্টার স্টক সিঙ্ক যেকোনো অবস্থায় পূরণ করে নেয়। প্রতিটি বিরতি Logs ট্যাবে রেকর্ড করা হয়।',
'Woo_Guide_Artisan_Exception' => 'একটি ব্যতিক্রম: artisan কমান্ড দিয়ে করা স্টক পরিবর্তনের পরে আসার মতো কোনো রেসপন্স নেই, তাই সেটি বরং {queue}-এ কিউ করা হয়। সেগুলোও দ্রুত পাঠাতে, সেই কিউটি খালি করুন:',
'Woo_Cron_Line_Copied' => 'Cron লাইন কপি হয়েছে',
'Woo_Command_Copied' => 'কমান্ড কপি হয়েছে',
'Woo_Guide_Not_Woo_Queue' => 'ইচ্ছাকৃতভাবে {queue} কিউ নয়: সেটি ঘণ্টার পর ঘণ্টা চলা ক্যাটালগ ব্যাচ বহন করে, এবং তার পেছনে কিউ করা একটি তাৎক্ষণিক পুশ আর তাৎক্ষণিক থাকত না।',
'Woo_On_A_Schedule' => 'শিডিউল অনুযায়ী',
'Woo_Guide_Scheduled_Lead' => 'সবকিছু নির্দিষ্ট সময় পরপর দুই দিকেই আবার যাচাই করা হয়। এভাবেই অর্ডার ERP-তে পৌঁছায়, ক্যাটালগ প্রকাশিত হয়, এবং দ্রুত পথে যা বাদ পড়েছে তা মেরামত হয়। প্রতিটি জবের নিজস্ব cron এন্ট্রি আছে, তাই আপনি শুধু যা চান তাই চালান।',
'Woo_Guide_Sync_Drains_Queue' => '{command} চলার সময় নিজের কিউ নিজেই খালি করে, তাই এই লাইনগুলোর জন্য আলাদা worker লাগে না। Windows-এ Task Scheduler ব্যবহার করুন, প্রোগ্রাম {program} এবং একই আর্গুমেন্ট সহ, {path}-এ শুরু করে।',
'Woo_Or_No_Cron' => 'অথবা কোনো cron ছাড়াই',
'Woo_Guide_No_Cron_Text' => 'এখানকার প্রতিটি ট্যাব চাহিদা অনুযায়ী সিঙ্ক করে, এবং পৃষ্ঠা খোলা থাকা অবস্থায় ম্যানুয়াল সিঙ্ক নিজের ব্যাচগুলো নিজেই সম্পন্ন করে — তাই একটি ছোট শপ কোনো cron এন্ট্রি ছাড়াই চলতে পারে। যা হারাবেন তা হলো কেউ না দেখার সময় ঘটে যাওয়া সবকিছু: কেউ বোতাম চাপলে তবেই অর্ডার আসে।',
'Woo_Commands_Worth_Knowing' => 'জেনে রাখার মতো কমান্ড',
'Woo_Worth_Knowing' => 'জেনে রাখুন',
'Woo_Guide_Changing_Url_Clears' => 'স্টোর URL বা API কী পরিবর্তন করলে সব ম্যাপিং মুছে যায় — পণ্য, ক্যাটাগরি, ব্র্যান্ড ও গ্রাহক সবই নতুন স্টোরে আবার সিঙ্ক হয়।',
'Woo_Guide_Keep_Skus' => 'Stocky ও WooCommerce-এর মধ্যে SKU একই রাখুন: এটিই ডুপ্লিকেট আটকায় এবং পুনরায় লিঙ্ক করাকে নিরাপদ করে।',
'Woo_Guide_Stock_Total' => 'Woo-তে প্রকাশিত স্টক হলো {total}, কোনো একটি গুদামের সংখ্যা নয়।',
'Woo_Total_Across_Warehouses' => 'সব গুদাম মিলিয়ে মোট',
'Woo_Guide_Full_Reference' => 'সম্পূর্ণ রেফারেন্স — প্রতিটি স্কোপ, কিউ কীভাবে আচরণ করে, এবং একটি সমস্যা সমাধান তালিকা — {file}-এ আছে।',
'Woo_Way_Covers' => 'অন্তর্ভুক্ত',
'Woo_Way_Covers_Realtime' => 'শুধু ERP থেকে বের হওয়া স্টক — একটি POS বিক্রয়, একটি রিটার্ন, একটি সমন্বয়, একটি গৃহীত ক্রয়',
