'Woo_Settings_Auto_Products_Hint' => 'Stocky-তে তৈরি, সম্পাদিত বা ডুপ্লিকেট করা পণ্য সংরক্ষণের ঠিক পরেই WooCommerce-এ পাঠানো হয় — বিবরণ, মূল্য, ভ্যারিয়েন্ট, ছবি, তারপর তার স্টক — পণ্য সিঙ্কের অপেক্ষা না করে। বাল্ক ইমপোর্ট পুশ হয় না; ইমপোর্টের পর একটি পণ্য সিঙ্ক চালান।',
'Woo_Sync_Tuning' => 'সিঙ্ক টিউনিং',
'Woo_Sync_Tuning_Intro' => 'ডিফল্ট মানগুলো বেশিরভাগ স্টোরের জন্য উপযুক্ত। আপনার হোস্টিংয়ে সিঙ্ক ধীর হলে বা টাইমআউট হলে তবেই এগুলো পরিবর্তন করুন। প্রতিটি মান একটি নিরাপদ সীমার মধ্যে সীমাবদ্ধ, এবং কোনো ঘর খালি করলে তার ডিফল্ট মান ফিরে আসে।',
