'Telegram_G_Chat_Id_Note' => '{json} খুঁজুন। গ্রুপ বা চ্যানেলের ID ঋণাত্মক হয়, যেমন {example} — মাইনাস চিহ্নসহ পুরোটা কপি করুন।',
