'Telegram_G_How_Sent' => 'মেসেজ কীভাবে পাঠানো হয়',
'Telegram_G_A_Title' => 'সঙ্গে সঙ্গে — কিছু ইনস্টল করার নেই',
'Telegram_G_A_Body' => 'Stocky-তে সংরক্ষিত একটি বিক্রয়, ক্রয়, পেমেন্ট বা ব্যয় — POS-এ বা অ্যাডমিনে — সংরক্ষণের {after} একই রিকোয়েস্টে Telegram-এ পাঠানো হয়। কোনো cron এন্ট্রি নেই, কোনো queue worker নেই, এবং ক্যাশিয়ারকে কখনো Telegram-এর জন্য অপেক্ষা করতে হয় না: মেসেজ যাওয়ার সময় বিক্রয়ের উত্তর ইতিমধ্যে দেওয়া হয়ে গেছে।',
'Telegram_G_Right_After' => 'ঠিক পরেই',
'Telegram_G_B_Title' => 'cron এন্ট্রি — পুনঃচেষ্টা ও ব্যাকগ্রাউন্ড ইভেন্টের জন্য',
'Telegram_G_B_Body' => 'দুই ধরনের মেসেজ বরং Telegram-এর নিজস্ব কিউতে অপেক্ষা করে: যে পাঠানো ব্যর্থ হয়েছে (Telegram কিছুক্ষণের জন্য পৌঁছানো যায়নি), যা পরবর্তী কয়েক মিনিটে আরও তিনবার পর্যন্ত পুনঃচেষ্টা করা হয়; এবং অ্যাডমিনের বাইরে উদ্ভূত ইভেন্ট — WooCommerce বা Shopify থেকে ইমপোর্ট করা অর্ডার, artisan কমান্ড। এই cron এন্ট্রি সেগুলো পাঠায়, আর কিছু নয়:',
'Telegram_G_Cron_Note' => 'প্রতি মিনিটই সঠিক: অপেক্ষমাণ কিছু না থাকলে রান সঙ্গে সঙ্গে শেষ হয়। cPanel-এ এটি {cronJobs}-এ যায় — {php} পুরোনো হলে PHP 8.2+-এর পূর্ণ পাথ ব্যবহার করুন। Windows-এ Task Scheduler ব্যবহার করুন, প্রোগ্রাম {program}, আর্গুমেন্ট {args}, {path}-এ শুরু করে।',
