'Salla_Guide_4' => 'অ্যাপের Webhooks পৃষ্ঠায়: {signature} নিরাপত্তা কৌশল বেছে নিন, এর সিক্রেট এখানকার Webhook সিক্রেট ফিল্ডে কপি করুন, Connection ট্যাবে দেখানো Webhook URL সেট করুন, এবং অন্তত {e1}, {e2}, {e3}, {e4}, {e5} ও {e6}-এ সাবস্ক্রাইব করুন।',
'Salla_Guide_5' => '{connect}-এ ক্লিক করুন এবং আপনার স্টোরে অ্যাপটি অনুমোদন করুন। (Easy Mode-এর অ্যাপগুলো বরং {webhook} Webhook-এর মাধ্যমে স্বয়ংক্রিয়ভাবে সংযুক্ত হয়।)',
'Salla_Guide_6' => 'পণ্য পুল বা পুশ করুন, তারপর স্টক পুশ করুন। নতুন অর্ডার স্বয়ংক্রিয়ভাবে আসে এবং {ref}-এর মতো রেফারেন্সসহ বিক্রয়ের অধীনে দেখা যায়।',
'Salla_Identity_Sku_Title' => 'পণ্যের পরিচয় হলো SKU',
'Salla_Identity_Sku_Desc' => 'Stocky-এর পণ্য কোড Salla-র SKU-এর সাথে মেলানো হয়। দুই দিকেই SKU একই রাখুন; ভ্যারিয়েন্ট পণ্য পুল করার সময় ও অর্ডারে মেলানো হয়, তবে এই ভার্সনে পুশ করা হয় না।',
