'Presta_Shop_Language_Id' => 'শপের ভাষা ID',
'Presta_Shop_Language_Help' => 'পুশ করার সময় পণ্যের নামের জন্য ব্যবহৃত ভাষা id (1 = শপের প্রথম ভাষা)।',
'Presta_Push_Products_Desc' => 'PrestaShop-এ অনুপস্থিত সাধারণ পণ্য তৈরি করে (তাদের বর্তমান স্টকসহ)। ইতিমধ্যে লিঙ্ক করা পণ্য ও ভ্যারিয়েন্ট পণ্য বাদ দেওয়া হয় — পণ্যের বিবরণ PrestaShop-এই সম্পাদনা করতে থাকুন, অথবা স্থানীয় কপি রিফ্রেশ করতে পুল করুন।',
'Presta_Pull_Products_Desc' => 'PrestaShop-এর পণ্য ইমপোর্ট করে, বিদ্যমানগুলো রেফারেন্স (SKU) দিয়ে মিলিয়ে এবং বাকিগুলো তৈরি করে। কম্বিনেশনগুলো তাদের প্যারেন্ট পণ্য হিসেবে ইমপোর্ট করা হয়।',
'Presta_Reset_Product_Confirm' => 'পণ্য লিঙ্ক রিসেট করবেন? অর্ডার ইতিহাসের লিঙ্কগুলো থেকে যাবে।',
'Presta_Push_Stock_Desc' => 'প্রতিটি লিঙ্ক করা পণ্যের জন্য শপের স্টক (stock_availables) আপডেট করে।',
'Presta_Pull_Orders_Desc' => 'শপের অর্ডার বিক্রয় হিসেবে ইমপোর্ট করে ({ref}-এর মতো রেফারেন্স), নতুনগুলো আগে। ইতিমধ্যে ইমপোর্ট করা ও বাতিল অর্ডার বাদ দেওয়া হয়, তাই নিয়মিত পুল করা নিরাপদ। PrestaShop-এ কোনো Webhook নেই — ব্যস্ত সময়ের পর এটি চালান।',
'Presta_Guide_1' => 'আপনার PrestaShop ব্যাক অফিসে {menu} খুলুন এবং webservice সক্রিয় করুন।',
'Presta_Guide_2' => 'একটি নতুন কী যোগ করুন, {products} ও {stock}-এ {rw} এবং {orders} ও {customers}-এ {view} অনুমতি দিয়ে।',
'Presta_Guide_3' => 'Connection ট্যাবে স্টোর URL ও কী পেস্ট করুন, সংরক্ষণ করুন, এবং {test} চালান।',
'Presta_Guide_4' => 'শপে আগে থেকেই ক্যাটালগ থাকলে প্রথমে পণ্য পুল করুন (রেফারেন্স/SKU দিয়ে মেলায়); অনুপস্থিত সাধারণ পণ্য তৈরি করতে পুশ করুন।',
'Presta_Guide_5' => 'পরিমাণ পরিবর্তন হলেই স্টক পুশ করুন, এবং নিয়মিত অর্ডার পুল করুন — PrestaShop-এ কোনো Webhook নেই, তাই পুল করলে তবেই অর্ডার আসে।',
'Presta_Identity_Title' => 'পণ্যের পরিচয় হলো রেফারেন্স (SKU)',
'Presta_Identity_Desc' => 'Stocky-এর পণ্য কোড PrestaShop-এর রেফারেন্সের সাথে মেলানো হয়। দুই দিকেই রেফারেন্স একই রাখুন; কম্বিনেশন (ভ্যারিয়েন্ট) অর্ডারে রেফারেন্স দিয়ে মেলানো হয় তবে এই ভার্সনে পুশ করা হয় না।',
