'Xero_Push_Customers' => 'গ্রাহক পুশ করুন',
'Xero_Push_Sales_Invoices' => 'বিক্রয় ইনভয়েস হিসেবে পুশ করুন',
'Xero_Push_Invoices_Desc' => 'প্রতিটি বিক্রয়ের জন্য একটি AUTHORISED ইনভয়েস তৈরি করে (ইনভয়েস নম্বর = বিক্রয়ের Ref), বিক্রয়ের লাইন আইটেমসহ শিপিং, ছাড় ও কর লাইন যোগ করে যাতে Xero-র মোট বিক্রয়ের মোটের সাথে মেলে। ইতিমধ্যে Xero-তে থাকা বিক্রয় বাদ দেওয়া হয় — ইনভয়েস কখনো সম্পাদনা করা হয় না। অনুপস্থিত কন্টাক্ট সঙ্গে সঙ্গে তৈরি করা হয়।',
'Xero_Push_Invoices' => 'ইনভয়েস পুশ করুন',
'Xero_Reset_Contact_Confirm' => 'কন্টাক্ট লিঙ্ক রিসেট করবেন? পরবর্তী পুশ সেগুলো পুনরায় লিঙ্ক বা পুনরায় তৈরি করবে।',
'Xero_Reset_Contact_Links' => 'কন্টাক্ট লিঙ্ক রিসেট করুন',
'Xero_Guide_1' => '{link}-এ একটি {webApp} তৈরি করুন ({menu})।',
'Xero_Guide_2' => 'Connection ট্যাবে দেখানো redirect URI নিবন্ধন করুন।',
'Xero_Guide_3' => 'অ্যাপের {clientId} কপি করুন এবং একটি {clientSecret} তৈরি করুন; দুটিই এখানে পেস্ট করে সংরক্ষণ করুন।',
'Xero_Guide_4' => '{connect}-এ ক্লিক করুন, সাইন ইন করুন এবং সংযুক্ত করার প্রতিষ্ঠান বেছে নিন।',
'Xero_Guide_5' => 'অ্যাকাউন্ট কোডগুলো যাচাই করুন: বিক্রয় অ্যাকাউন্ট ইনভয়েস লাইন গ্রহণ করে; পরিশোধিত বিক্রয়ে পেমেন্টও রেকর্ড করতে চাইলে একটি ব্যাংক অ্যাকাউন্ট কোড সেট করুন।',
'Xero_Guide_6' => 'প্রথমে গ্রাহক, তারপর ইনভয়েস পুশ করুন। ইনভয়েস নম্বর হলো বিক্রয়ের Ref, তাই লিঙ্ক রিসেট করলেও Xero ডুপ্লিকেট প্রত্যাখ্যান করে।',
'Xero_Amounts_Title' => 'পরিমাণগুলো যেমন আছে তেমন কর-সহ পুশ করা হয়',
'Xero_Amounts_Desc' => 'ইনভয়েসে NoTax লাইন ব্যবহার করা হয় যা হুবহু বিক্রয়ের প্রতিফলন (আইটেম + শিপিং − ছাড় + কর), তাই Xero-র মোট সবসময় Stocky-র মোটের সমান হয়। আপনার হিসাবরক্ষক Xero-র ভেতরে কর ও শিপিং লাইনগুলো যথাযথ অ্যাকাউন্টে পুনরায় ম্যাপ করতে পারেন।',
