'Jumia_Hero_Desc' => 'আপনার Jumia Seller Center লিস্টিংয়ে মূল্য ও স্টক পুশ করুন এবং মার্কেটপ্লেসের অর্ডার বিক্রয় হিসেবে ইমপোর্ট করুন।',
