'Jumia_Prices_Stock' => 'মূল্য ও স্টক',
'Jumia_Push_Prices_Stock_Title' => 'Jumia-তে মূল্য ও স্টক পুশ করুন',
'Jumia_Push_Prices_Stock_Desc' => 'যেসব পণ্যের (ও ভ্যারিয়েন্টের) SKU Jumia লিস্টিংয়ের {sku}-এর সাথে মেলে, সেগুলোর বর্তমান মূল্য ও পরিমাণ পাঠায়। আপডেটগুলো Seller Center ফিড হিসেবে জমা দেওয়া হয় এবং অ্যাসিঙ্ক্রোনাসভাবে প্রয়োগ হয় — ফিড ID Logs ট্যাবে রেকর্ড করা হয়, এবং আইটেমভিত্তিক প্রত্যাখ্যান Seller Center-এর ফিড স্ট্যাটাস স্ক্রিনে দেখা যায়।',
'Jumia_Push_Prices_Stock' => 'মূল্য ও স্টক পুশ করুন',
'Jumia_Pull_Orders_Desc' => 'মার্কেটপ্লেসের অর্ডার বিক্রয় হিসেবে ইমপোর্ট করে ({ref}-এর মতো রেফারেন্স), Seller SKU দিয়ে আপনার পণ্যের সাথে মিলিয়ে। ইতিমধ্যে ইমপোর্ট করা ও বাতিল অর্ডার বাদ দেওয়া হয়, তাই নিয়মিত পুল করা নিরাপদ। শুধু ডেলিভার হওয়া অর্ডারের পেমেন্ট পরিশোধিত হিসেবে চিহ্নিত হয় (Jumia-তে মূলত COD)।',
'Jumia_Guide_1' => 'Jumia {sellerCenter}-এ {menu} খুলুন এবং একটি API কী তৈরি করুন।',
'Jumia_Guide_2' => 'আপনার দেশের API URL দিন (যেমন নাইজেরিয়ার জন্য {ng}, কেনিয়ার জন্য {ke}, মিশরের জন্য {eg}), আপনার Seller Center অ্যাকাউন্ট ইমেইল, এবং কী — তারপর {test} চালান।',
'Jumia_Guide_3' => 'নিশ্চিত করুন যে প্রতিটি Jumia লিস্টিংয়ের {sku} Stocky পণ্য কোডের সমান — স্টক পুশ ও অর্ডার মেলানো দুটির জন্যই এটিই পরিচয়।',
'Jumia_Guide_4' => 'ইনভেন্টরি পরিবর্তনের পর মূল্য ও স্টক পুশ করুন; নিয়মিত অর্ডার পুল করুন (এই API-তে Jumia-র কোনো Webhook নেই)।',
'Jumia_Guide_5' => 'নতুন লিস্টিং তৈরি Seller Center-এই থাকে — Jumia ক্যাটাগরি-নির্দিষ্ট অ্যাট্রিবিউট ও ছবি পর্যালোচনা চায় যা শুধু তাদের পোর্টালই ভালোভাবে সামলায়।',
