'Mailchimp_Double_Optin_Off_Desc' => 'নতুন সদস্যরা কোনো নিশ্চিতকরণ ইমেইল ছাড়াই সাবস্ক্রাইবড হিসেবে যুক্ত হবেন। শুধু সেই গ্রাহকদের জন্য এটি করুন যারা ইতিমধ্যে মার্কেটিং গ্রহণে সম্মত হয়েছেন।',
