'GSheets_Guide_2' => '{consent} কনফিগার করুন (External)। এটি "Testing"-এ থাকা অবস্থায় আপনার Google অ্যাকাউন্টকে টেস্ট ব্যবহারকারী হিসেবে যোগ করুন — মনে রাখবেন টেস্টিং মোডের রিফ্রেশ টোকেন ৭ দিন পর মেয়াদোত্তীর্ণ হয়, তাই স্থায়ী সংযোগের জন্য অ্যাপটি {publish} করুন।',
