'Shopify_Already_Subscribed' => 'এই স্টোরের প্রয়োজনীয় সবকিছুতে ইতিমধ্যে সাবস্ক্রাইব করা আছে',
'Shopify_Could_Not_Register' => 'ওয়েবহুক রেজিস্টার করা যায়নি',
'Shopify_Sub_Removed' => 'সাবস্ক্রিপশন সরানো হয়েছে',
'Shopify_Could_Not_Remove_Sub' => 'ওই সাবস্ক্রিপশনটি সরানো যায়নি',
'Shopify_Could_Not_Load_Store' => 'এই স্টোরটি লোড করা যায়নি',
'Shopify_G_Lead_Store' => 'এই শপকে নিজেকে হালনাগাদ রাখতে যা যা প্রয়োজন। এখানের সবকিছু এই স্টোরের জন্য নির্দিষ্ট — পাথ ও ID-গুলো আসল, তাই কমান্ডগুলো সরাসরি সার্ভারে কপি করা যায়।',
'Shopify_G_Lead_Generic' => 'একটি Shopify শপ কীভাবে ERP-এর সাথে নিজেকে হালনাগাদ রাখে। এর নিজস্ব অবস্থা দেখতে উপরে একটি স্টোর বেছে নিন, অথবা যেমন আছে তেমন পড়ুন — আপনি যে স্টোরই সংযুক্ত করুন, ক্রন লাইন ও ওয়েবহুক URL একই।',
'Shopify_G_Ways_Note' => 'বেশিরভাগ শপ দুটোই চালায়: প্রথমটি শপকে প্রতি মিনিটে হালনাগাদ রাখে, দ্বিতীয়টি প্রথমটি যা মিস করেছে তা ধরে — যে ওয়েবহুক কখনো পৌঁছায়নি, Shopify অ্যাডমিনে সরাসরি করা কোনো সম্পাদনা, এমন একটি রাত যখন সাইট বন্ধ ছিল।',
'Shopify_G_Both_Need' => 'দুই পদ্ধতিতেই প্রথমে এটি প্রয়োজন',
'Shopify_G_Credentials' => 'Shopify ক্রেডেনশিয়াল',
'Shopify_G_Cred_Intro' => 'জানুয়ারি ২০২৬ থেকে Shopify আর অ্যাডমিনের ভেতরে কাস্টম অ্যাপ তৈরি করে না, তাই দুই ধরনের সংযোগ আছে:',
'Shopify_G_Cred_DevDash' => '{app} (এখন সংযুক্ত যেকোনো শপ) — {path}। এই স্টোর যা সিঙ্ক করে তার জন্য Admin API স্কোপ দিন, শপে অ্যাপটি ইনস্টল করুন, তারপর অ্যাপের Settings পেজ থেকে {clientId} ও {clientSecret} কপি করে {where}-এ বসান। ERP নিজেই এগুলোর বিনিময়ে একটি অ্যাক্সেস টোকেন নেয় এবং প্রতি ২৪ ঘণ্টায় মেয়াদ শেষ হওয়ার আগে তা নবায়ন করে। client secret ওয়েবহুকও সাইন করে, তাই আর কিছু প্রয়োজন নেই। অ্যাপ ও শপ অবশ্যই একই Shopify অর্গানাইজেশনে থাকতে হবে।',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard অ্যাপ',
'Shopify_G_Cred_Legacy' => '{app} (২০২৬-এর আগে অ্যাডমিনে তৈরি) — এর {token} ({prefix}) এবং ওয়েবহুক সাইনিং সিক্রেট হিসেবে এর {secret} দিয়ে অপরিবর্তিতভাবে কাজ করতে থাকে। এটি টোকেনের মতো একই মান নয়, এবং এ দুটো উল্টাপাল্টা করাই ওয়েবহুক প্রত্যাখ্যাত হওয়ার সাধারণ কারণ।',
'Shopify_G_Legacy_App' => 'লিগ্যাসি কাস্টম অ্যাপ',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'সংরক্ষিত',
'Shopify_G_Missing_Refused' => 'অনুপস্থিত — ডেলিভারি প্রত্যাখ্যাত হবে',
'Shopify_G_Where_Data_Desc' => '{path} যে ERP গুদামের স্টক এই শপ বিক্রি করে, এবং যে Shopify লোকেশনে সেই স্টক লেখা হয়। এগুলো ছাড়া ইনভেন্টরি সিঙ্ক ও অর্ডার ইমপোর্ট কোনোটিই চলবে না।',
'Shopify_G_Currently' => 'বর্তমানে: গুদাম {warehouse}, লোকেশন {location}',
'Shopify_G_Not_Set_Lower' => 'সেট করা নেই',
'Shopify_G_Ready' => 'প্রস্তুত',
'Shopify_G_Incomplete' => 'অসম্পূর্ণ',
'Shopify_G_Manual_Syncs' => 'যেসব সিঙ্ক আপনি হাতে শুরু করেন',
'Shopify_G_Manual_Desc' => '{centre} থেকে শুরু করা একটি সিঙ্ক সঙ্গে সঙ্গে সাড়া দেয় এবং ব্যাকগ্রাউন্ডে চলে, ছোট ছোট অংশে, প্রতিটি আগেরটি যেখানে থেমেছিল সেখান থেকে চালিয়ে যায়। দীর্ঘ ওয়েব রিকোয়েস্ট বন্ধ করে দেয় এমন হোস্টিং (LiteSpeed, nginx, লোড ব্যালান্সার) কখনো বড় ক্যাটালগকে মাঝপথে কেটে দেয় না, এবং পেজ বন্ধ করলেও এটি থামে না। এর জন্য ওয়ার্কার হলো আরও একটি ক্রন লাইন:',
'Shopify_G_Cron_Copied' => 'ক্রন লাইন কপি হয়েছে',
'Shopify_G_Manual_Note' => 'এটি ছাড়াও সিঙ্ক শেষ হয়, তবে শুধু যতক্ষণ Sync Centre পেজ খোলা থাকে: কয়েক সেকেন্ডের মধ্যে কোনো ওয়ার্কার রানটি না নিলে পেজ নিজেই এটি চালিয়ে যায়, একবারে একটি ছোট রিকোয়েস্ট করে। Windows-এ প্রতি মিনিটে Task Scheduler ব্যবহার করুন: প্রোগ্রাম {program}, আর্গুমেন্ট {args}, শুরু হবে {dir}-এ।',
'Shopify_G_Then_Pick' => 'তারপর বেছে নিন এটি কীভাবে হালনাগাদ থাকবে',
'Shopify_G_Right_Away' => 'সঙ্গে সঙ্গে',
'Shopify_G_Stock_Live' => 'স্টক লাইভ',
'Shopify_G_Stock_Not_Live' => 'স্টক লাইভ নয়',
'Shopify_G_Realtime_Lead' => 'প্রতিটি পরিবর্তন ঘটার সাথে সাথে, কয়েক সেকেন্ডে পাঠানো হয়। দুটি অংশ, এবং সেগুলো আলাদা সুইচ: {webhooks} শপের নিজস্ব ইভেন্ট নিয়ে আসে, এবং {push} স্টক বাইরে পাঠায়।',
'Shopify_G_Webhooks_Lower' => 'ওয়েবহুক',
'Shopify_G_Instant_Push_Lower' => 'তাৎক্ষণিক স্টক পুশ',
'Shopify_G_Webhooks_In' => 'ওয়েবহুক — শপ → ERP',
'Shopify_G_Webhooks_Desc' => 'Shopify-তে করা অর্ডার, অর্ডার স্ট্যাটাস পরিবর্তন, এবং পণ্য, গ্রাহক ও স্টক সম্পাদনা। স্টোরটি খুলুন এবং এর {tab}-এ {button} চাপুন — দুবার চাপলেও সমস্যা নেই। Shopify এখানে পোস্ট করে:',
'Shopify_G_Webhooks_Tab' => 'ওয়েবহুক ট্যাব',
'Shopify_G_Webhooks_Note' => 'ঠিকানাটি অবশ্যই ইন্টারনেট থেকে HTTPS-এর মাধ্যমে পৌঁছানো যোগ্য হতে হবে — Shopify {localhost} বা {test} ডোমেইনে ডেলিভার করবে না। প্রতিটি ডেলিভারি একবারই রেকর্ড হয়, তাই Shopify-এর পুনঃচেষ্টা ডুপ্লিকেট অর্ডার তৈরি করতে পারে না, এবং ব্যর্থ একটি পুনরায় চালানো যায়। ধাপ ১-এর সাইনিং সিক্রেট সংরক্ষণ না করা পর্যন্ত ডেলিভারি প্রত্যাখ্যাত হয়।',
'Shopify_G_Instant_Out' => 'তাৎক্ষণিক স্টক পুশ — ERP → শপ',
'Shopify_G_Setting_Missed' => 'এই সেটিংটি লোকে প্রায়ই মিস করে',
'Shopify_G_Pos_Not_Auto' => 'একটি POS বিক্রয় নিজে থেকে Shopify-তে {not} পৌঁছায়। বন্ধ রাখলে শপ শুধু পরবর্তী ইনভেন্টরি পুশ ধাপে জানতে পারে — এবং সেই সময়ের মধ্যে এটি এমন একটি ইউনিট বিক্রি করে ফেলতে পারে যা আপনি ইতিমধ্যে কাউন্টারে বিক্রি করেছেন।',
'Shopify_G_Not' => 'না',
'Shopify_G_Tick_Push' => '{where}-এ {setting} টিক দিন। এটুকুই পুরো সেটআপ — কোনো ওয়ার্কার নয়, কোনো ক্রন নয়। এরপর প্রতিটি বিক্রয়, রিটার্ন ও সমন্বয় বিক্রয় সংরক্ষণের ঠিক পরেই শুধু সংশ্লিষ্ট পণ্যগুলোর একটি পুশ পাঠায়, এবং বিশ লাইনের একটি বিক্রয়ে একটিই পুশ হয়, বিশটি নয়। ক্যাশ কাউন্টার কখনো এর জন্য অপেক্ষা করে না।',
'Shopify_G_This_Store' => 'এই স্টোর:',
'Shopify_G_Push_On' => 'চালু — পরিবর্তনে স্টক পুশ হয়',
'Shopify_G_Push_Off' => 'বন্ধ — স্টক শুধু সময়সূচি অনুযায়ী',
'Shopify_G_Push_Note' => 'শুধু যেসব পণ্যের ইতিমধ্যে Shopify ম্যাপিং আছে, এবং শুধু এই স্টোরের গুদামের মুভমেন্টই পুশ করা হয়। বাল্ক অপারেশন — একটি পণ্য মোছা, একটি গুদাম রিসেট করা — কোনো ইভেন্ট ছাড়াই স্টক লেখে, যা নির্ধারিত ইনভেন্টরি ধাপটিও রাখার একটি কারণ।',
'Shopify_G_Nothing_Install' => 'আর কিছু ইনস্টল করতে হবে না',
'Shopify_G_No_Worker_Note' => 'কোনো অংশেরই কিউ ওয়ার্কার বা ক্রন এন্ট্রি লাগে না। আগত একটি ওয়েবহুক Shopify-এর পাঠানো রিকোয়েস্টেই পরিচালিত হয়; বহির্গামী একটি স্টক পুশ সেই একই প্রসেসে চলে যা বিক্রয়টি পরিবেশন করেছে, রেসপন্স ফেরত যাওয়ার {after} — তাই ক্যাশ কাউন্টার কখনো Shopify-এর অপেক্ষায় থাকে না, এবং সাড়া না দেওয়া শপকে দশ সেকেন্ড পর ছেড়ে দিয়ে পরবর্তী নির্ধারিত ইনভেন্টরি পুশের জন্য রেখে দেওয়া হয়।',
'Shopify_G_After' => 'পরে',
'Shopify_G_Artisan_Note' => 'একটি ব্যতিক্রম: artisan কমান্ড দ্বারা করা স্টক পরিবর্তনের পরে আসার মতো কোনো রেসপন্স নেই, তাই সেটি এর বদলে {queue}-এ কিউ করা হয়। আপনি যদি সেগুলোও দ্রুত পাঠাতে চান, ওই কিউটি প্রসেস করুন:',
'Shopify_G_On_Schedule' => 'সময়সূচি অনুযায়ী',
'Shopify_G_On_Lower' => 'চালু',
'Shopify_G_Off_Lower' => 'বন্ধ',
'Shopify_G_Scheduled_Lead' => 'সবকিছু নির্দিষ্ট সময় পরপর, দুই দিকেই পুনরায় যাচাই করা হয়। রিয়েল টাইমের চেয়ে ধীর, তবে যেসব শপ তাৎক্ষণিক পুশ ব্যবহার করে না সেগুলোতে এটিই স্টক পাঠায়, মিস হওয়া ওয়েবহুক ধরে, এবং পুরো ক্যাটালগ আদান-প্রদানের একমাত্র উপায়।',
'Shopify_G_Cron_Entry' => 'ক্রন এন্ট্রি',
'Shopify_G_Cron_Entry_Desc' => 'এটি ছাড়া কোনো নির্ধারিত কাজ চলে না। একটি লাইন, শুধু এই মডিউলের জন্য — আপনি আর যা যা নির্ধারণ করেছেন তার পাশে এটি যোগ করুন:',
'Shopify_G_Cron_Note' => 'প্রতি পাঁচ মিনিট হলো একটি প্ল্যানের সর্বনিম্ন ব্যবধান, কারণ পাঁচ মিনিটই সবচেয়ে ছোট ধাপ ইন্টারভাল। এর চেয়ে বড় এন্ট্রি সর্বনিম্ন সীমা হয়ে যায় — {example} দিলে, ৫ মিনিটে সেট করা একটি ধাপ প্রতি ১৫ মিনিটে চলবে। Windows-এ Task Scheduler ব্যবহার করুন: প্রোগ্রাম {program}, আর্গুমেন্ট {args}, শুরু হবে {dir}-এ।',
'Shopify_G_Switch_On_Plan' => 'এটি চালু করুন, এবং প্ল্যান বেছে নিন',
