'Cr_Guide_Step_Book_Help' => 'বিক্রয় তালিকায়, একটি বিক্রয়ের মেনু খুলে কুরিয়ারে পাঠান নির্বাচন করুন, অথবা একাধিক বিক্রয়ে টিক দিয়ে একসাথে পাঠান।',
