'Cr_Guide_T_Statuses' => 'স্ট্যাটাস',
'Cr_Guide_Statuses_Note' => 'স্ট্যাটাস কেবল সামনের দিকে এগোয়, তাই দেরিতে আসা আপডেট কখনো পার্সেলকে পেছনে টেনে আনে না। ডেলিভারি হওয়া পার্সেলকেও ফেরত আসছে বা ফেরত এসেছে হিসেবে রিপোর্ট করা যেতে পারে।',
