'Cr_Guide_S_out_for_delivery' => 'আজ রাইডারের কাছে।',
'Cr_Guide_S_failed_attempt' => 'বাড়িতে নেই, প্রত্যাখ্যাত বা ভুল ঠিকানা। কুরিয়ার আবার চেষ্টা করবে বা ফেরত পাঠাবে।',
'Cr_Guide_S_delivered' => 'গ্রাহকের হাতে দেওয়া হয়েছে। COD পরিমাণ কুরিয়ার কর্তৃক সংগৃহীত হিসেবে গণ্য হয়।',
