'Cr_Guide_S_returned' => 'আপনার কাছে ফেরত এসেছে: এটি পর্যালোচনার জন্য রিটার্নে অপেক্ষা করে, অথবা স্বয়ংক্রিয়ভাবে রিস্টক হয়।',
'Cr_Guide_S_cancelled' => 'বুকিংটি বাতিল করা হয়েছে।',
'Cr_Guide_T_Booking' => 'অর্ডার বুকিং',
'Cr_Guide_B_Booking' => 'কুরিয়ারে পাঠান বিক্রয় থেকে ফর্মটি পূরণ করে: প্রাপক, ঠিকানা, COD হিসেবে এখনো বাকি পরিমাণ এবং পণ্যের ওজন। যে কুরিয়ারগুলোর নিজস্ব শহরের তালিকা আছে সেগুলো একটি পিকার দেখায়, এবং আপনার পছন্দ সেই শহরের জন্য মনে রাখা হয়। অ্যাগ্রিগেটর, DHL, FedEx, UPS এবং Lalamove রেট তুলনার সুযোগ দেয়: একটি মূল্য বেছে নিন এবং বুক করুন সেটি কিনে নেয়। বিক্রয় তালিকা থেকে একসাথে একাধিক বিক্রয় বুক করা যায়।',
'Cr_Guide_T_Cod' => 'ক্যাশ অন ডেলিভারি',
'Cr_Guide_B_Cod' => 'একটি COD পার্সেল সংগৃহীত হয়নি থেকে কুরিয়ার কর্তৃক সংগৃহীত (ডেলিভারির সময়) হয়ে আপনাকে পরিশোধিত-এ যায়। যে কুরিয়ারগুলো পেআউট রিপোর্ট করে তারা শেষ ধাপটি নিজেই সম্পন্ন করে; অন্যদের জন্য COD আপডেট করুন ব্যবহার করুন। কুরিয়ার সেটিংসে একটি অ্যাকাউন্ট বেছে নেওয়া থাকলে, পেআউট বিক্রয়ের উপর একটি পেমেন্ট হিসেবে রেকর্ড হয়। পার্সেল সম্পন্ন হলে কুরিয়ার চার্জ ব্যয় হিসেবে সংরক্ষণ করা যায়।',
'Cr_Guide_T_Returns' => 'ফেরত আসা পার্সেল',
'Cr_Guide_B_Returns' => 'ডিফল্টভাবে একটি ফেরত আসা পার্সেল কুরিয়ার শিপমেন্টে পর্যালোচনার জন্য রিটার্নের অধীনে অপেক্ষা করে। রিস্টক পুরো অর্ডারের জন্য একটি বিক্রয় রিটার্ন তৈরি করে এবং আইটেমগুলো স্টকে ফিরিয়ে দেয়; খারিজ কিছুই ফেরত দেয় না, ক্ষতিগ্রস্ত বা হারানো পার্সেলের জন্য। এর পরিবর্তে কুরিয়ার সেটিংস স্বয়ংক্রিয়ভাবে রিস্টক করতে পারে।',
'Cr_Guide_T_Customers' => 'গ্রাহক বার্তা ও ট্র্যাকিং পেজ',
'Cr_Guide_B_Customers' => 'কুরিয়ার সেটিংসে গ্রাহক নোটিফিকেশন আপনার টিক দেওয়া স্ট্যাটাসগুলোতে আপনার নিজস্ব টেক্সটসহ SMS, ইমেইল বা WhatsApp পাঠায়, প্রতিটি পার্সেলে একবার করে। আপনার অনলাইন স্টোরের ট্র্যাকিং পেজ গ্রাহকদের ট্র্যাকিং নম্বর, অথবা অর্ডার নম্বর ও ফোন দিয়ে পার্সেল অনুসরণ করতে দেয়। যে গ্রাহকরা প্রায়ই পার্সেল ফেরত দেন, বুক করার সময় তাদের একটি রিটার্ন-ঝুঁকি ব্যাজ দেখানো হয়।',
'Cr_Guide_T_Labels' => 'লেবেল',
'Cr_Guide_B_Labels' => 'লেবেল প্রিন্ট করুন কুরিয়ার নিজস্ব লেবেল দিলে সেটি দেয় (একটি PDF, একটি লিংক বা একটি ছবি), অন্যথায় ট্র্যাকিং বারকোড ও সংগ্রহযোগ্য পরিমাণসহ একটি Stocky লেবেল দেয়। প্রিন্ট করতে এই সাইটের জন্য পপ-আপ অনুমতি দিন। DHL, FedEx এবং UPS তাদের লেবেল কেবল একবার, বুকিংয়ের সময় দেয়, এবং Stocky পুনঃপ্রিন্টের জন্য তা সংরক্ষণ করে রাখে।',
'Cr_Guide_T_Faq' => 'সমস্যা সমাধান',
'Cr_Guide_Q_Test' => 'টেস্ট কানেকশন ব্যর্থ হয়',
'Cr_Guide_A_Test' => 'টেস্ট-মোড কী টেস্ট মোডের সাথে এবং লাইভ কী লাইভের সাথে যায়; এগুলো ভিন্ন। সঠিক কারণ জানতে কুরিয়ার লগ খুলে কুরিয়ারের উত্তর পড়ুন।',
'Cr_Guide_Q_City' => 'কুরিয়ার শহর বা ঠিকানা প্রত্যাখ্যান করে',
'Cr_Guide_A_City' => 'বুকিং ফর্মে কুরিয়ারের শহর তালিকা থেকে শহর বেছে নিন; কুরিয়ার কেবল তাদের নিজস্ব নামগুলো গ্রহণ করে। যে কুরিয়ারগুলো পোস্টাল ঠিকানা নিয়ে কাজ করে তাদের রাজ্য/বিভাগ, পোস্টাল কোড এবং দুই-অক্ষরের দেশ কোডও প্রয়োজন।',
'Cr_Guide_Q_Webhook' => 'স্ট্যাটাস নিজে থেকে পরিবর্তিত হয় না',
'Cr_Guide_A_Webhook' => 'যে কুরিয়ারগুলো পুশ করে, তাদের ক্ষেত্রে Webhook URL কুরিয়ারে নিবন্ধিত আছে কিনা যাচাই করুন: কুরিয়ার লগ প্রাপ্ত প্রতিটি আপডেট দেখায়, অথবা কেন একটি প্রত্যাখ্যাত হয়েছে (যেমন ভুল সিক্রেট)। অন্য কুরিয়ারগুলো কুরিয়ার সেটিংসের সময়সূচি অনুযায়ী যাচাই করা হয়, এবং এখনই স্ট্যাটাস যাচাই করুন সঙ্গে সঙ্গে জিজ্ঞাসা করে।',
'Cr_Guide_Q_Stuck' => 'একটি শিপমেন্টে স্ট্যাটাস যাচাই ত্রুটি দেখাচ্ছে',
'Cr_Guide_A_Stuck' => 'কুরিয়ার শেষ যাচাইগুলো প্রত্যাখ্যান করেছে; কারণটি শিপমেন্টে এবং কুরিয়ার লগে আছে। বারবার ব্যর্থ হওয়ার পর একটি শিপমেন্ট আর স্বয়ংক্রিয়ভাবে যাচাই করা হয় না: কারণটি ঠিক করুন, তারপর এখনই স্ট্যাটাস যাচাই করুন ব্যবহার করুন।',
'Cr_Guide_Q_Label' => 'লেবেল প্রিন্ট করার সময় কিছুই খোলে না',
'Cr_Guide_A_Label' => 'আপনার ব্রাউজার পপ-আপ ব্লক করেছে। এই সাইটের জন্য পপ-আপ অনুমতি দিন এবং আবার চেষ্টা করুন।',
