'Cr_Guide_A_Cod' => 'কুরিয়ার সেটিংসে, ক্যাশ অন ডেলিভারির জন্য সুইচ চালু থাকা এবং একটি অ্যাকাউন্ট বেছে নেওয়া প্রয়োজন। অ্যাকাউন্ট ছাড়া, পেআউট কেবল পরিশোধিত হিসেবে চিহ্নিত হয়।',
