'Tfa_Off_Help' => 'একটি দ্বিতীয় সাইন-ইন ধাপ যোগ করুন: আপনার ফোনের অথেনটিকেটর অ্যাপ থেকে একটি 6-সংখ্যার কোড, যেমন Google Authenticator, Microsoft Authenticator বা Authy।',
'Tfa_Codes_Left' => 'অবশিষ্ট রিকভারি কোড: :count',
'Tfa_Required_Notice' => 'আপনার অ্যাডমিনিস্ট্রেটর টু-ফ্যাক্টর অথেনটিকেশন বাধ্যতামূলক করেছেন। এখন চালু না করলে, আপনার পরবর্তী সাইন-ইনে এটি সেট আপ করতে বলা হবে।',
'Tfa_Required_By_Admin' => 'আপনার অ্যাডমিনিস্ট্রেটর কর্তৃক বাধ্যতামূলক',
'Tfa_Turn_On' => 'চালু করুন',
'Tfa_Turn_Off' => 'বন্ধ করুন',
'Tfa_Turn_On_Title' => 'টু-ফ্যাক্টর অথেনটিকেশন চালু করুন',
'Tfa_Turn_Off_Title' => 'টু-ফ্যাক্টর অথেনটিকেশন বন্ধ করুন',
'Tfa_Turned_On' => 'টু-ফ্যাক্টর অথেনটিকেশন চালু আছে।',
'Tfa_Turned_Off' => 'টু-ফ্যাক্টর অথেনটিকেশন বন্ধ আছে।',
'Tfa_New_Codes' => 'নতুন রিকভারি কোড',
'Tfa_Confirm_Password' => 'চালিয়ে যেতে আপনার বর্তমান পাসওয়ার্ড লিখুন।',
'Tfa_Continue' => 'চালিয়ে যান',
'Tfa_Step_Install' => 'আপনার ফোনে একটি অথেনটিকেটর অ্যাপ ইনস্টল করুন।',
'Tfa_Step_Scan' => 'এই QR কোডটি স্ক্যান করুন, অথবা নিচের কী-টি টাইপ করুন।',
'Tfa_Step_Confirm' => 'অ্যাপে দেখানো 6-সংখ্যার কোডটি লিখুন।',
'Tfa_Enter_Code' => 'অ্যাপ থেকে 6-সংখ্যার কোডটি লিখুন।',
'Tfa_Qr_Failed' => 'QR কোড উপলব্ধ নয় — এর পরিবর্তে কী-টি টাইপ করুন।',
'Tfa_Copy' => 'কপি করুন',
'Tfa_Copied' => 'কপি করা হয়েছে',
'Tfa_Download' => 'ডাউনলোড',
'Tfa_Done' => 'সম্পন্ন',
'Tfa_Codes_Save' => 'এই রিকভারি কোডগুলো কোনো নিরাপদ জায়গায় সংরক্ষণ করুন। ফোন হারালে প্রতিটি কোড দিয়ে একবার সাইন ইন করা যায়। এগুলো আর দেখানো হবে না।',
'Tfa_Reset' => 'টু-ফ্যাক্টর রিসেট করুন',
'Tfa_Reset_Title' => 'টু-ফ্যাক্টর অথেনটিকেশন রিসেট করবেন?',
'Tfa_Reset_Help' => ':name কেবল পাসওয়ার্ড দিয়ে সাইন ইন করবেন এবং তারপর আবার তার অথেনটিকেটর অ্যাপ সেট আপ করতে পারবেন। কে অনুরোধ করছেন তা নিশ্চিত হওয়ার পরেই কেবল এটি করুন।',
'Tfa_Guide_Lead' => 'টু-ফ্যাক্টর অথেনটিকেশন (2FA) সাইন-ইনে একটি দ্বিতীয় ধাপ যোগ করে: পাসওয়ার্ডের পরে, কর্মীরা তাদের ফোনের অথেনটিকেটর অ্যাপ থেকে একটি 6-সংখ্যার কোড টাইপ করেন। চুরি হওয়া বা অনুমান করা পাসওয়ার্ড দিয়ে আর প্রবেশ করা যায় না।',
'Tfa_Guide_State_Required' => 'বাধ্যতামূলক',
'Tfa_Guide_State_Optional' => 'না — সবার জন্য ঐচ্ছিক',
'Tfa_Guide_State_Trust' => 'বিশ্বস্ত ডিভাইস',
'Tfa_Guide_State_Users' => '2FA চালু থাকা ব্যবহারকারী',
'Tfa_Guide_Staff_Title' => 'প্রত্যেক কর্মীর জন্য',
'Tfa_Guide_App_Title' => 'একটি অথেনটিকেটর অ্যাপ ইনস্টল করুন',
'Tfa_Guide_App_Text' => 'স্ট্যান্ডার্ড 6-সংখ্যার কোড (TOTP) সমর্থন করে এমন যেকোনো অ্যাপ কাজ করে। এগুলো বিনামূল্যে এবং অফলাইনে কাজ করে:',
'Tfa_Guide_Enable_Title' => 'প্রোফাইল থেকে এটি চালু করুন',
'Tfa_Guide_Enable_1' => 'প্রোফাইল খুলুন (উপরে ডানদিকে অ্যাভাটার মেনু) এবং "টু-ফ্যাক্টর অথেনটিকেশন" কার্ডটি খুঁজুন।',
'Tfa_Guide_Enable_2' => '"চালু করুন" ক্লিক করুন এবং বর্তমান পাসওয়ার্ড দিয়ে নিশ্চিত করুন।',
'Tfa_Guide_Enable_3' => 'অ্যাপ দিয়ে QR কোডটি স্ক্যান করুন, অথবা এর নিচে দেখানো কী-টি টাইপ করুন।',
'Tfa_Guide_Enable_4' => 'শেষ করতে অ্যাপে দেখানো 6-সংখ্যার কোডটি লিখুন।',
'Tfa_Guide_Open_Profile' => 'আমার প্রোফাইল খুলুন',
'Tfa_Guide_Codes_Title' => 'রিকভারি কোড সংরক্ষণ করুন',
'Tfa_Guide_Codes_Text' => 'সেটআপের ঠিক পরেই 8টি রিকভারি কোড একবার দেখানো হয়। প্রতিটি কোড একবার ফোনের কোডের বিকল্প হিসেবে কাজ করে — হারানো, ভাঙা বা রিসেট করা ফোনের জন্য। এগুলো ডাউনলোড বা কপি করে ফোন থেকে দূরে কোনো নিরাপদ জায়গায় রাখুন।',
'Tfa_Guide_Codes_Note' => 'কোড ফুরিয়ে আসছে? প্রোফাইলের "নতুন রিকভারি কোড" পুরো সেটটি প্রতিস্থাপন করে; পুরনোগুলো আর কাজ করে না।',
'Tfa_Guide_Signin_Title' => 'সাইন ইন করা',
'Tfa_Guide_Signin_Text' => 'ইমেইল ও পাসওয়ার্ডের পরে, লগইন পেজ অ্যাপ থেকে বর্তমান কোডটি চায়। কোডগুলো প্রতি 30 সেকেন্ডে পরিবর্তিত হয় এবং প্রতিটি একবার কাজ করে।',
'Tfa_Guide_Signin_Trust' => '"এই ডিভাইসে আর জিজ্ঞাসা করবেন না" টিক দিলে সেই ব্রাউজারে :days দিনের জন্য কোড চাওয়া হয় না।',
'Tfa_Guide_Signin_Recovery' => 'হাতের কাছে ফোন নেই? "একটি রিকভারি কোড ব্যবহার করুন" ক্লিক করুন এবং সংরক্ষিত কোডগুলোর একটি টাইপ করুন।',
'Tfa_Guide_Admin_Title' => 'অ্যাডমিনিস্ট্রেটরদের জন্য',
'Tfa_Guide_Require_Title' => 'এটি বাধ্যতামূলক করুন',
'Tfa_Guide_Require_Text' => 'এই কার্ডে "টু-ফ্যাক্টর অথেনটিকেশন বাধ্যতামূলক করুন" চালু করুন, তারপর যে রোলগুলোকে এটি ব্যবহার করতেই হবে সেগুলো বেছে নিন — অথবা প্রত্যেক ব্যবহারকারীর জন্য তালিকা খালি রাখুন। সংরক্ষণ করতে "জমা দিন" ক্লিক করুন।',
'Tfa_Guide_Require_Next' => 'কাউকে সাইন আউট করা হয় না। যাদের এখনো 2FA নেই তাদের পরবর্তী সাইন-ইনে, প্রবেশের আগে লগইন পেজে সেটআপের ধাপগুলো দেখানো হয়, এবং সেখানেই তারা তাদের রিকভারি কোড দেখতে পান।',
'Tfa_Guide_Require_Note' => 'যাদের জন্য এটি বাধ্যতামূলক তারা নিজেদের প্রোফাইল থেকে এটি বন্ধ করতে পারেন না।',
'Tfa_Guide_Trust_Title' => 'বিশ্বস্ত ডিভাইস',
'Tfa_Guide_Trust_Text' => '"বিশ্বস্ত ডিভাইস মনে রাখুন" নির্ধারণ করে সফল সাইন-ইনের পরে একটি ব্রাউজার কতদিন কোড ছাড়া চলতে পারবে। শেয়ার করা বা পাবলিক কম্পিউটারের জন্য, যেমন দোকানের POS, "সবসময় কোড জিজ্ঞাসা করুন" বেছে নিন।',
'Tfa_Guide_Trust_Note' => 'সংখ্যা কমালে ইতিমধ্যে বিশ্বস্ত ডিভাইসগুলোর মেয়াদও কমে; 2FA বন্ধ বা রিসেট করলে সবগুলো ভুলে যাওয়া হয়।',
'Tfa_Guide_Lost_Title' => 'ফোন হারিয়েছে এবং রিকভারি কোড নেই',
'Tfa_Guide_Lost_Text' => 'ব্যবহারকারী পেজে, 2FA থাকা ব্যবহারকারীদের 2FA কলামে "চালু" দেখায়। অ্যাকশনের শিল্ড বাটন এটি রিসেট করে: ব্যবহারকারী কেবল পাসওয়ার্ড দিয়ে সাইন ইন করেন এবং আবার অ্যাপ সেট আপ করেন (অথবা বাধ্যতামূলক হলে করতে বলা হয়)।',
'Tfa_Guide_Lost_Warn' => 'রিসেট করার আগে কে অনুরোধ করছেন তা নিশ্চিত করুন — রিসেট সেই অ্যাকাউন্ট থেকে 2FA-এর সুরক্ষা সরিয়ে দেয়।',
'Tfa_Guide_Open_Users' => 'ব্যবহারকারী খুলুন',
'Tfa_Guide_Mobile_Title' => 'মোবাইল অ্যাপ ও API',
'Tfa_Guide_Mobile_Text' => 'মোবাইল অ্যাপ ও API টোকেন এন্ডপয়েন্ট একই কোড চায়। যদি এমন কোনো ব্যবহারকারীর জন্য 2FA বাধ্যতামূলক হয় যিনি এখনো সেট আপ করেননি, তাকে তা করতে একবার ওয়েবে সাইন ইন করতে হবে।',
'Tfa_Guide_Protect_Title' => 'বিল্ট-ইন সুরক্ষা',
'Tfa_Guide_Protect_1' => '5টি ভুল কোড সেই ব্যবহারকারীর কোড প্রবেশ 15 মিনিটের জন্য ব্লক করে, উপরের লকআউট সেটিংস যা-ই হোক না কেন।',
'Tfa_Guide_Protect_2' => 'প্রতিটি কোড ও প্রতিটি রিকভারি কোড কেবল একবার কাজ করে।',
'Tfa_Guide_Protect_3' => '"সাইন-ইন কার্যকলাপ রেকর্ড করুন" চালু থাকলে, ভুল কোডগুলো সাইন-ইন কার্যকলাপ তালিকায় "ভুল 2FA কোড" হিসেবে দেখায়।',
'Tfa_Guide_Trouble_Title' => 'সমস্যা সমাধান',
'Tfa_Guide_Faq_Clock_Q' => 'নতুন কোড দিয়েও “কোডটি বৈধ নয়”',
'Tfa_Guide_Faq_Clock_A' => 'সম্ভবত ফোনের ঘড়ি ঠিক নেই। কোডগুলো সময়ের উপর নির্ভর করে: ফোনের তারিখ ও সময় স্বয়ংক্রিয় (নেটওয়ার্ক সময়) এ সেট করুন, তারপর পরবর্তী কোডটি চেষ্টা করুন।',
'Tfa_Guide_Faq_Phone_Q' => 'নতুন ফোনে স্থানান্তর',
'Tfa_Guide_Faq_Phone_A' => 'হয় অথেনটিকেটর অ্যাপের নিজস্ব ট্রান্সফার ফিচার ব্যবহার করুন, অথবা প্রোফাইলে 2FA বন্ধ করে নতুন ফোন দিয়ে আবার চালু করুন (বাধ্যতামূলক হলে, এর পরিবর্তে একজন অ্যাডমিনকে রিসেট করতে বলুন)।',
'Tfa_Guide_Faq_Locked_Q' => '“অনেকবার অবৈধ কোড”',
'Tfa_Guide_Faq_Locked_A' => 'দেখানো সময় পর্যন্ত অপেক্ষা করুন (সর্বোচ্চ 15 মিনিট), অথবা একজন অ্যাডমিনকে দিয়ে ব্যবহারকারীর 2FA রিসেট করান।',
'Tfa_Guide_Faq_Key_Q' => 'সার্ভার স্থানান্তরের পর 2FA থাকা কেউ সাইন ইন করতে পারছে না',
'Tfa_Guide_Faq_Key_A' => '2FA সিক্রেটগুলো .env ফাইলের APP_KEY দিয়ে এনক্রিপ্ট করা থাকে। অ্যাপ স্থানান্তর বা রিস্টোর করার সময় একই APP_KEY রাখুন; এটি পরিবর্তিত হলে, 2FA ছাড়া একজন অ্যাডমিনকে প্রভাবিত ব্যবহারকারীদের রিসেট করতে হবে।',
'Tfa_Guide_Button' => 'গাইড',
'Tfa_Guide_Title' => 'টু-ফ্যাক্টর অথেনটিকেশন গাইড',
'Sec_2fa_Pending' => ':count জনের এখনো সেট আপ করা বাকি',
'Sec_2fa_See_Who' => 'কারা দেখুন',
