'Tfa_Guide_Rollout_Title' => 'প্রত্যেক ব্যবহারকারীর জন্য চালু করুন',
'Tfa_Guide_Rollout_1' => 'প্রথমে নিজের অ্যাকাউন্টের জন্য চালু করুন (প্রোফাইল), যাতে আপনি ধাপগুলো জানেন।',
'Tfa_Guide_Rollout_2' => 'আপনার টিমকে জানান কোন অ্যাপ ইনস্টল করতে হবে এবং সাইন-ইনের সময় সেটআপে এক মিনিট লাগে।',
'Tfa_Guide_Rollout_3' => '"টু-ফ্যাক্টর অথেনটিকেশন বাধ্যতামূলক করুন" চালু করুন, "যাদের জন্য বাধ্যতামূলক" খালি রাখুন (= প্রত্যেক ব্যবহারকারী), এবং ঐচ্ছিকভাবে একটি গ্রেস পিরিয়ড বেছে নিন। "জমা দিন" ক্লিক করুন।',
'Tfa_Guide_Rollout_4' => '"2FA ছাড়া ব্যবহারকারীদের সাইন আউট করুন" ক্লিক করুন যাতে ইতিমধ্যে সাইন ইন থাকা ব্যক্তিরা পরের কোনো সাইন-ইনের বদলে এখনই এটি সেট আপ করেন। আপনি সাইন ইন অবস্থায় থাকবেন।',
'Tfa_Guide_Rollout_5' => 'এই কার্ডের কাউন্টার বা ব্যবহারকারী পেজের "সেটআপ প্রয়োজন" ফিল্টার দিয়ে অগ্রগতি অনুসরণ করুন।',
'Tfa_Guide_Rollout_Note' => 'গ্রেস পিরিয়ড থাকলে, সেটআপ স্ক্রিনে শেষ সময় পর্যন্ত “পরে মনে করিয়ে দিন” দেখায়; এর পরে, সাইন ইন করতে সেটআপ বাধ্যতামূলক।',
'Tfa_Guide_Customers_Title' => 'গ্রাহক অ্যাকাউন্ট (স্টোর ও ক্লায়েন্ট পোর্টাল)',
'Tfa_Guide_Customers_Text' => 'গ্রাহকরাও তাদের নিজস্ব অ্যাকাউন্ট সুরক্ষিত করতে পারেন। এটি প্রত্যেক গ্রাহকের জন্য ঐচ্ছিক এবং কখনো বাধ্য করা হয় না: স্টোর সেটিংস → রেজিস্ট্রেশন অ্যাক্সেস কন্ট্রোল (অনলাইন স্টোর) এবং ক্লায়েন্ট পোর্টাল → পোর্টাল সেটিংস (ক্লায়েন্ট পোর্টাল) থেকে এটি চালু করুন।',
'Tfa_Guide_Customers_1' => 'গ্রাহকরা আমার অ্যাকাউন্ট (স্টোর) বা প্রোফাইল (পোর্টাল) থেকে এটি চালু করেন।',
'Tfa_Guide_Customers_2' => 'তারা ইমেইলে পাঠানো কোড বেছে নেন — সবচেয়ে সহজ, কোনো অ্যাপ লাগে না — অথবা রিকভারি কোডসহ একটি অথেনটিকেটর অ্যাপ।',
'Tfa_Guide_Customers_3' => 'ইমেইলে পাঠানো কোডের জন্য কার্যকর মেইল সেটিংস প্রয়োজন (সেটিংস → মেইল সেটিংস)। এগুলোর মেয়াদ 10 মিনিট পর শেষ হয়।',
'Tfa_Guide_Customers_4' => 'পরে অপশনটি বন্ধ করলে নতুন সেটআপ বন্ধ হয়; যে গ্রাহকরা ইতিমধ্যে এটি ব্যবহার করছেন তাদের কাছে কোড চাওয়া চলতে থাকে এবং তারা নিজেরাই এটি বন্ধ করতে পারেন।',
'Tfa_Required_Grace_Notice' => 'আপনার অ্যাডমিনিস্ট্রেটর টু-ফ্যাক্টর অথেনটিকেশন বাধ্যতামূলক করেছেন। আপনি :date পর্যন্ত সাইন-ইনের সময় এটি স্থগিত রাখতে পারবেন; এর পরে সেটআপ বাধ্যতামূলক।',
'Tfa_Filter_All' => '2FA: সকল ব্যবহারকারী',
'Tfa_Needs_Setup_Help' => 'সিস্টেম সেটিংস > সিকিউরিটি অনুযায়ী বাধ্যতামূলক; পরবর্তী সাইন-ইনে এটি সেট আপ করতে বলা হবে।',
