'Store_Customer_2fa_Help' => 'গ্রাহকদের ইমেইলে পাঠানো কোড বা অথেনটিকেটর অ্যাপের কোড দিয়ে তাদের অ্যাকাউন্ট সুরক্ষিত করতে দেয়, যা আমার অ্যাকাউন্ট থেকে চালু করা হয়। প্রত্যেক গ্রাহকের জন্য ঐচ্ছিক।',
